(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c73"]=[{"id":"00015526","register_sub_id":"101","register_pk":"533541","name":"紫藤家住宅内蔵","kana":"しどうけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中央区水道町3-32","lat":32.804325,"lng":130.71266389,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0207","desc":"敷地西寄りに建つ家財蔵で主屋と廊下で接続する。二階建切妻造平入桟瓦葺で、外壁は全面白漆喰塗とし軒に鉢巻、腰に二段の水切を廻らす。東面戸口に掛子塗戸を開き、内部は各階一室で、小屋はキングポスト・トラス。窓に塗込の袖壁を付す重厚な外観の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015526"},{"id":"00015525","register_sub_id":"101","register_pk":"533540","name":"紫藤家住宅主屋","kana":"しどうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市中央区水道町3-32","lat":32.80431667,"lng":130.71275556,"geo_status":"db","era":"明治後期／平成19年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積280㎡","structure_material":"木造平屋一部2階建","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0206","desc":"市街地中心部に位置する旧実業家の住宅主屋。庭に南面する平屋建寄棟造桟瓦葺東西棟で、内部は続き間座敷とし、周囲に玄関や台所、茶室を接続する。西座敷は付書院を櫛形窓とし、室境に透欄間を建てるなど上質な意匠。市街地中心部に残る希少な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015525"},{"id":"00011013","register_sub_id":"101","register_pk":"208983","name":"新麹屋柏原家住宅主屋","kana":"しんこうじやかしわばらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市小川町小川字上刈萱58","lat":32.585258,"lng":130.707731,"geo_status":"db","era":"明治16／明治31増築・昭和42改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積197㎡","structure_material":"木造平屋一部2階建","registered":"2016.02.25(平成28.02.25)","register_no":"43-0153","desc":"旧薩摩街道に南面する二階建、入母屋造妻入で、前面を塗込め、居蔵造の外観になる。東半の通り土間と三室の当初部は軸部重厚で、増築された座敷部は、正面に玄関を構え、欄間や座敷飾りに上質な意匠を備える。家業の隆盛とともに拡張した経緯を良く示す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011013"},{"id":"00013903","register_sub_id":"101","register_pk":"507861","name":"新麹屋柏原家住宅中庭塀","kana":"しんこうじやかしわばらけじゅうたくなかにわへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱58-1","lat":32.58534722,"lng":130.707825,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、延長12m","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"43 － 0183","desc":"旧薩摩街道に南面する。既登録の主屋・離れ間に建つ中庭の塀。布石の上に半間毎に柱を立て、壁は黒漆喰塗で腰を煉瓦積とし、上部に襷桟の欄間を設けて屋根は桟瓦葺。丸鋼で控えをとる。腰の煉瓦積を市松風に配する意匠が目を引く。屋敷景観の一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013903"},{"id":"00011014","register_sub_id":"101","register_pk":"208984","name":"新麹屋柏原家住宅離れ","kana":"しんこうじやかしわばらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県宇城市小川町小川字上刈萱58","lat":32.585435,"lng":130.707783,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡、渡廊下付","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"43-0154","desc":"主屋座敷部の奥に渡廊下を介して東西棟で建つ、入母屋造桟瓦葺。隠居屋として建てられた、建ちの高い二階建で、上下階とも東西二室の前後に廊下を通し、東室を主室としてトコと付書院を備える。筬欄間や付書院の組子細工などに大正期らしい洗練さが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011014"},{"id":"00011015","register_sub_id":"101","register_pk":"208985","name":"新麹屋柏原家住宅門及び塀","kana":"しんこうじやかしわばらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県宇城市小川町小川字上刈萱58","lat":32.58518516,"lng":130.70766077,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"門 木造、瓦葺、間口2.0m 塀 木造、瓦葺、総延長12m","structure_material":"門 木造","registered":"2016.02.25(平成28.02.25)","register_no":"43-0155","desc":"南正面の西寄り、主屋座敷部の玄関前方に開く門と左右にのびる塀。門は一間薬医門、切妻造桟瓦葺で本柱間に板戸内開きとする。塀は人造石洗出しの基礎上に建ち、真壁漆喰塗で欄間を透かし、屋根桟瓦葺とする。端正な意匠の門塀で、主屋の接客機能充実を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011015"},{"id":"00016456","register_sub_id":"101","register_pk":"536523","name":"堤家住宅主屋","kana":"つつみけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市五日町28-1","lat":32.21389167,"lng":130.76314444,"geo_status":"db","era":"昭和前期／昭和9年頃増築、令和6年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積402㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0214","desc":"人吉城跡の北西、球磨川沿岸の敷地に位置する洋館付き和風住宅。北棟は北面中央に玄関を設け、西に洋館を付し、南棟は５室を配して北棟と接続し、エの字形平面を呈する。主座敷は広縁を介して川を望み、床框や付書院枠を漆塗とするなど上質な近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016456"},{"id":"00016620","register_sub_id":"101","register_pk":"574982","name":"内藤家住宅主屋","kana":"ないとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市南区刈草二丁目1441","lat":32.80323861,"lng":130.70814722,"geo_status":"db","era":"明治14年／明治41年・昭和35年・令和2年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造2階建、瓦葺、建築面積304㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"43 - 0225","desc":"市街地南方の住宅地に位置する旧実業家の主屋。敷地中央に南面する二階建入母屋造桟瓦葺で、正面西寄りに式台を設ける。一階は東に土間、西に六室、二階は七室を配し、南西庭に面する座敷は簡素ながらも堅実な設え。大型で建ちが高く、上質な近代和風の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016620"},{"id":"00015267","register_sub_id":"101","register_pk":"530691","name":"野尻家住宅主屋","kana":"のじりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市天水町小天字南横内4203","lat":32.86661389,"lng":130.59843333,"geo_status":"db","era":"江戸末期／明治後期・昭和前期増築、同30年代改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積367㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"43 - 0203","desc":"玉名市天水町の丘陵中腹に位置する在御家人の住宅主屋。東を土間、西を中庭を囲うコの字形に居室を配し、南正面を座敷、北奥を離れとする。座敷はマツの良材を用い、書院欄間に意匠性に富む龍の彫刻を施す。大規模で、眺望に優れた座敷を持つ上質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015267"},{"id":"00015268","register_sub_id":"101","register_pk":"530692","name":"野尻家住宅門及び塀","kana":"のじりけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市天水町小天字南横内4203-1","lat":32.86631111,"lng":130.59843056,"geo_status":"db","era":"安政4年(1857)","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"門 木造、瓦葺、建築面積10㎡、袖塀付 塀 木造、瓦葺、総延長18m","structure_material":"門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"43 - 0204","desc":"石垣に沿う斜路上端に構えた門と塀。門は切妻造桟瓦葺の四脚門で角柱を用い、中央に大きな板扉を開く。土間は角石布敷。両脇に落棟の袖壁を設け、北側に木戸を開く。石垣上に廻らせた真壁造桟瓦葺の塀と一体となって在御家人住宅の風格ある屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015268"},{"id":"00006462","register_sub_id":"101","register_pk":"107445","name":"浜田醤油主屋","kana":"はまだしょうゆしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77709917,"lng":130.63596552,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0094","desc":"店舗の南隣に建つ、桁行４間半、梁間３間半、木造２階建、切妻造桟瓦葺で、下屋を廻す。内部は和室２室を上下に配する。外部は塗り込め、腰を海鼠壁とし、窓に格子を嵌めるなど、店舗と統一感のある重厚な外観である。海鼠壁は目地漆喰を隅切りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006462"},{"id":"00014307","register_sub_id":"101","register_pk":"509697","name":"林家住宅主屋","kana":"はやしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県上益城郡益城町大字小谷字荒瀬33","lat":32.81077222,"lng":130.862925,"geo_status":"db","era":"万延元年（1861）頃／昭和中期改修・平成元年移築","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積227㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"43 - 0192","desc":"阿蘇外輪西裾の集落に所在する在宅侍衆の旧宅。木造平屋建で屋根は東を入母屋、西を寄棟とし、南面して建つ。正面側中央の表の間の玄関に式台の痕跡を残し、西上手に上質な床構え付座敷を配して切目縁を回す。在宅侍衆と呼ばれた武士の住宅として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014307"},{"id":"00003931","register_sub_id":"101","register_pk":"104921","name":"氷川町まちつくり酒屋（旧井芹家住宅）外塀","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）そとへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.55627745,"lng":130.68198561,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、延長14m","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0071","desc":"敷地の西端で南北に延びる延長１４ｍの外塀。腰を縦板張，上部を真壁造とし，腕木で桟瓦葺の小屋根を支える。漆喰壁に１間おきに連子窓を穿ち，屋敷内側には腕木と込栓留された溶結凝灰岩の角柱を２間おきに据えて控えをとるなど，丁寧な仕事を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003931"},{"id":"00003929","register_sub_id":"101","register_pk":"104919","name":"氷川町まちつくり酒屋（旧井芹家住宅）門","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.5562628,"lng":130.68228547,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、間口1.9m、袖塀付","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0069","desc":"主屋北側に位置する。木造，桟瓦葺，薬医門形式の堂々としたつくりで，たたきに彩色されたタイルを埋め込む凝ったつくりとする。主屋とも接続する袖塀は，右側に通用門が穿たれ，腰を亀甲模様の海鼠壁で築くなど，門とともに質の高い造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003929"},{"id":"00003930","register_sub_id":"101","register_pk":"104920","name":"氷川町まちつくり酒屋（旧井芹家住宅）煉瓦塀","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）れんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.55629256,"lng":130.6822226,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"煉瓦造、延長20m","structure_material":"煉瓦造","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0070","desc":"門の北側から西方に延び敷地境に建ち上げられた壁。２枚厚の赤煉瓦をイギリス積とした延長２０ｍの煉瓦壁で，屋敷側には約３ｍおきに半枚厚の控壁付を配する。雨仕舞に配慮して壁体の頂部にコーニスを付けるなど，簡素な造りながら工夫が凝らされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003930"},{"id":"00001989","register_sub_id":"101","register_pk":"102979","name":"藤崎家住宅（赤松館）表門","kana":"ふじさきけじゅうたく（せきしょうかん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36206955,"lng":130.51261027,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、間口5.8m、木製門扉及び左右袖塀付","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0041","desc":"石柱一対を立て，両開き板扉を吊り込んで門口を構成し，正面向かって左手の袖塀には潜戸を設ける。天草産と推定される長大な砂岩による門柱を立て，柱頭には繰形のある笠石を置いて飾り，簡素だが堂々たる構えを造っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001989"},{"id":"00001987","register_sub_id":"101","register_pk":"102977","name":"藤崎家住宅（赤松館）篭部屋","kana":"ふじさきけじゅうたく（せきしょうかん）かごべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36241276,"lng":130.51238048,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0039","desc":"主に竹篭や薪を収納する施設で，主屋釜屋のすぐ脇にある。桁行１０間，梁間１間の桁行に長い建物で，外壁は塀とひとつづきとなり，敷地側柱間は一部を除いて吹き放しとする。屋敷西辺を区切る位置に建ち，この面の景観を整える要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001987"},{"id":"00001988","register_sub_id":"101","register_pk":"102978","name":"藤崎家住宅（赤松館）米蔵","kana":"ふじさきけじゅうたく（せきしょうかん）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36261711,"lng":130.51231804,"geo_status":"db","era":"明治期／昭和5移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積247㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0040","desc":"２階建，桟瓦葺の土蔵で，１階は内部を２区画，２階は広い１室とし，正面の桁行全長にわたって下屋を深く葺き降ろす。得米を貯蔵するための施設として昭和５年に現在地に移築されたもので，建築面積約２５０平方メートルに及ぶ大規模な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001988"},{"id":"00001991","register_sub_id":"101","register_pk":"102981","name":"藤崎家住宅（赤松館）下の門","kana":"ふじさきけじゅうたく（せきしょうかん）したのもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.362305,"lng":130.512314,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造、瓦葺、間口2.3m、木製門扉付","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0043","desc":"味噌蔵の北背後，篭部屋との間に開いた門で，主屋台所脇の作業庭に通じる。棟門形式，桟瓦葺の簡素な構えだが，間口を大きく取り，幅広の板戸を片開きとするなど，物品の搬出入や車輌の出入りの便を考慮した特徴ある造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001991"},{"id":"00001984","register_sub_id":"101","register_pk":"102974","name":"藤崎家住宅（赤松館）主屋","kana":"ふじさきけじゅうたく（せきしょうかん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36233272,"lng":130.51255872,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積769㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0036","desc":"江戸時代後期より代々庄屋を務めた大地主の邸宅で，主屋は座敷部を中心に居間，台所・釜屋等の各部からなり，全体で７６８平方メートルに及ぶ規模を有する。座敷部，居間部の各室は，銘木を用いた巧緻な意匠になり，高い水準の大工技術を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001984"},{"id":"00001986","register_sub_id":"101","register_pk":"102976","name":"藤崎家住宅（赤松館）長屋","kana":"ふじさきけじゅうたく（せきしょうかん）ながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36217731,"lng":130.51241624,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0038","desc":"味噌蔵に隣接し真中の門の脇に建つ建物で，かっては下男の居所として使われていた。桁行２間，梁間１間半，切妻造，桟瓦葺の小規模で簡素な建物だが，西隣の味噌蔵や東方の塀と外観を統一し，屋敷の表構えを構成する重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001986"},{"id":"00001992","register_sub_id":"101","register_pk":"102982","name":"藤崎家住宅（赤松館）塀","kana":"ふじさきけじゅうたく（せきしょうかん）へい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36252185,"lng":130.51304216,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造、瓦葺、延長161m","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0044","desc":"米蔵とその前方の菜園を除いた敷地主要部分の四周を区切る。瓦葺の板塀で，正面及び東側面では一段高く築く。正面では，漆喰壁と腰部下見板張りが表門をはさんで延べ約３０メートルにわたって連続し，屋敷の正面構えを構成する重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001992"},{"id":"00001990","register_sub_id":"101","register_pk":"102980","name":"藤崎家住宅（赤松館）真中の門","kana":"ふじさきけじゅうたく（せきしょうかん）まんなかのもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.36210131,"lng":130.51253586,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造、瓦葺、間口1.9m、木製門扉及び東側塀延長15m付","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0042","desc":"長屋（下男部屋）の東に接して建つ日常の出入りのための門で，主屋の台所部土間に開いた通用口に通じる。間口一間の小規模で簡素な構えだが，格子組の引違透し戸とともに潜戸付き大戸を備え，桟瓦葺屋根に目地漆喰を施すなど，丁寧な造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001990"},{"id":"00001985","register_sub_id":"101","register_pk":"102975","name":"藤崎家住宅（赤松館）味噌蔵","kana":"ふじさきけじゅうたく（せきしょうかん）みそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県葦北郡芦北町大字田浦字五反田781-2他","lat":32.362221,"lng":130.5123259,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"43 － 0037","desc":"自家用の味噌，醤油を製造，貯蔵するための土蔵。２階建，切妻造，桟瓦葺で，東面には桁行全長に片流れの蔵前を設ける。敷地南西隅の目立つ位置に妻を正面に向けて建ち，漆喰壁と半間毎に立つ柱との対比によって，外観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001985"},{"id":"00015269","register_sub_id":"101","register_pk":"530693","name":"古荘家住宅（旧谷家住宅）主屋","kana":"ふるしょうけじゅうたく（きゅうたにけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県上益城郡益城町大字島田字櫛嶋屋敷1006-1","lat":32.75681389,"lng":130.78486667,"geo_status":"db","era":"明治後期／昭和32年・平成15年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積195㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"43 - 0205","desc":"木山川南岸の農村集落にある旧家の主屋。つし二階建切妻造桟瓦葺で周囲に下屋を廻し、正面に式台玄関を突出する。平面は六間取で、砂壁仕上とする座敷は付書院を備え、床と床脇にケヤキとマツの一枚板を用いるなど上質。式台を構えて旧家の格式をみせる主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015269"},{"id":"00009685","register_sub_id":"101","register_pk":"194681","name":"宮村家住宅石垣","kana":"みやむらけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県菊池市西寺字雷1075","lat":32.96946939,"lng":130.77593855,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、総延長46m","structure_material":"石造","registered":"2013.06.21(平成25.06.21)","register_no":"43 － 0125","desc":"敷地南面に東西に築かれた石垣で、上部植栽し、東寄りに出入口を設ける。阿蘇山に因む溶結凝灰岩を布積で台形断面に積上げ、総延長四六メートルを測る。現在は高さ一メートル弱だが、周辺を埋立てられる前は二倍近い高さであった。屋敷前面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009685"},{"id":"00009684","register_sub_id":"101","register_pk":"194680","name":"宮村家住宅主屋","kana":"みやむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県菊池市西寺字雷1075","lat":32.9696383,"lng":130.77594066,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積364㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"43 － 0124","desc":"田園地帯に南面して建ち、木造平屋建、寄棟造桟瓦葺で、四周に下屋を廻す。自家の山林から厳選した良材や銘木を多用し、東寄りの広い土間上部では重厚な梁組を現し、座敷では阿蘇五岳を刻んだ欄間を飾るなど上質なつくりとし、当地の大型民家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009684"},{"id":"00001157","register_sub_id":"101","register_pk":"102147","name":"矢野家住宅（新宅）主屋","kana":"やのけじゅうたく（しんたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2525","lat":32.81489114,"lng":130.89132679,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造平屋建一部２階建，瓦葺，建築面積241㎡","structure_material":"石造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0025","desc":"矢野家本宅から明治末年に分家した家で，屋敷地は本宅の東に隣接する。主屋は河原村の村長をつとめた矢野数馬が建てた。玄関付で屋根を２重にした外観や床と書院を備えた本格的座敷をもつ点等によく時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001157"},{"id":"00001155","register_sub_id":"101","register_pk":"102145","name":"矢野家住宅（本宅）裏門","kana":"やのけじゅうたく（ほんたく）うらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造薬医門，瓦葺，間口2.1m，板塀附属","structure_material":"木造薬医門","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0023","desc":"屋敷地北側にある道路からわずかに引き込んだ位置に建つ切妻造，桟瓦葺，一間一戸の薬医門。小規模ながら表門と同様に武家屋敷風の門で，左右には屋根付の板塀が接続してのび，北側の屋敷構えを整える役割をはたしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001155"},{"id":"00001154","register_sub_id":"101","register_pk":"102144","name":"矢野家住宅（本宅）表門","kana":"やのけじゅうたく（ほんたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造薬医門，瓦葺，間口2.7m，土塀附属","structure_material":"木造薬医門","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0022","desc":"味噌蔵の南方，屋敷地正面側にある道路からわずかに引き込んだ位置に建つ主屋玄関へと通じる門。切妻造，桟瓦葺，一間一戸の薬医門で，左右に屋根付の土塀が接続し，太い親柱を用いるなど武家屋敷風の意匠になる点は主屋と共通している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001154"},{"id":"00001151","register_sub_id":"101","register_pk":"102141","name":"矢野家住宅（本宅）倉","kana":"やのけじゅうたく（ほんたく）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造平屋建一部２階建，瓦葺，建築面積171㎡，竹塀附属","structure_material":"石造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0019","desc":"主屋南方の屋敷地境に建つ。一部２階建，桟瓦葺，妻入の比較的に規模の大きな土蔵で，腰をなまこ壁，上部を漆喰壁で仕上げ，開口部の上方や側面の中程に水切り瓦を付けるなど凝った意匠になる。地主としての繁栄を示す建物としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001151"},{"id":"00001150","register_sub_id":"101","register_pk":"102140","name":"矢野家住宅（本宅）主屋","kana":"やのけじゅうたく（ほんたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"石造平屋建一部２階建，瓦葺，建築面積333㎡，板塀・竹塀附属","structure_material":"石造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0018","desc":"矢野家は武家の流れをひく家で，明治期に近隣の地主をつとめた。主屋は玄関・座敷等に武家屋敷と類似点がみられ，この地方における明治初期の大規模住宅の好例である。座敷次の間の棟札によって明治６年の建築であることがわかる(一部は明治２２年の増築)。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001150"},{"id":"00001156","register_sub_id":"101","register_pk":"102146","name":"矢野家住宅（本宅）中門","kana":"やのけじゅうたく（ほんたく）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造薬医門，瓦葺，間口1.8m，竹塀附属","structure_material":"木造薬医門","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0024","desc":"主屋と表門との間をつなぐ屋根付の竹塀の中間に開かれた切妻造，桟瓦葺，一間一戸の小規模で簡素な薬医門。屋敷地の南方に広がる畑等への出入口となる門で，附属する竹塀とともに表門から主屋へと通じる道筋の景観を整える役割も果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001156"},{"id":"00001153","register_sub_id":"101","register_pk":"102143","name":"矢野家住宅（本宅）納屋","kana":"やのけじゅうたく（ほんたく）なや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造平屋建一部２階建，瓦葺，建築面積58㎡，板塀附属","structure_material":"石造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0021","desc":"味噌蔵の北方，屋敷地正面側にある道路に面して建つ横長の建物。一部２階建，桟瓦葺で，壁を真壁造にするなど倉に比較して簡略な形式になるが，道路側と両側面には軒桁下に近い位置まで下見板が貼られ，道路側からみた景観に配慮がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001153"},{"id":"00001152","register_sub_id":"101","register_pk":"102142","name":"矢野家住宅（本宅）味噌倉","kana":"やのけじゅうたく（ほんたく）みそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県阿蘇郡西原村大字河原2524","lat":32.81459223,"lng":130.89094466,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造平屋建一部２階建，瓦葺，建築面積22㎡，板塀附属","structure_material":"石造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"43 － 0020","desc":"主屋の西方，屋敷地正面側にある道路に面して建つ妻入の小規模な土蔵。一部２階建，桟瓦葺で，壁面は漆喰仕上げとするが，道路に面した正面側だけは腰に下見板を貼り，左右に連なる板塀と高さをあわせて屋敷構えの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001152"},{"id":"00011429","register_sub_id":"101","register_pk":"209266","name":"吉岡家住宅阿弥陀堂","kana":"よしおかけじゅうたくあみだどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県山鹿市鹿本町来民字今古閑2032-2","lat":32.99652,"lng":130.726272,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.8㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"43－0161","desc":"主屋の南に北面して建つ。北半は一間四方の板敷で、正側面を開放とし、南に壇を構えて側背面を板壁、前面を格子戸両開として阿弥陀如来を安置する。切妻造桟瓦葺で装飾はなく簡素な建物であるが、礼拝の場として、敷地の景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011429"},{"id":"00011427","register_sub_id":"101","register_pk":"209264","name":"吉岡家住宅江戸蔵","kana":"よしおかけじゅうたくえどぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市鹿本町来民字今古閑2032-2","lat":32.996498,"lng":130.726185,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"43－0159","desc":"熊本市京町から移築したと伝える土蔵。主屋の南方、敷地の南西隅に建つ。桁行三間、梁間二間、切妻造桟瓦葺。主屋に面した北妻東寄りに扉口を開き、内部は一・二階とも一室とする。腰部を板貼りとする他は漆喰塗とし、屋敷地の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011427"},{"id":"00011426","register_sub_id":"101","register_pk":"209263","name":"吉岡家住宅主屋","kana":"よしおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市鹿本町来民字今古閑2034","lat":32.996731,"lng":130.72631,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積309㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"43－0158","desc":"山鹿中心街の東南方に位置する豪農の居宅。主屋は木造一部二階建、東面する入母屋造桟瓦葺で、土間の北側に二列六室を配し、土間脇のオモテには玄関が取り付く。二階を設ける部分の一階を根太天井とする以外は棹縁天井とする。明治期の地域の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011426"},{"id":"00011431","register_sub_id":"101","register_pk":"209268","name":"吉岡家住宅塀","kana":"よしおかけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市鹿本町来民字今古閑2034","lat":32.996929,"lng":130.726484,"geo_status":"db","era":"明治16頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造、鉄板葺、総延長35m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"43－0163","desc":"薬医門の北側に接し、主屋の東側から北側にかけて伸びる。割石積基礎の上に土台石を並べ、竪板張の上部を透いてたすき桟を入れ、上部は笠木を通して鉄板葺の屋根を載せる。薬医門と同じく主屋整備と同時期に建てられ、近代初頭の地域の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011431"},{"id":"00011428","register_sub_id":"101","register_pk":"209265","name":"吉岡家住宅明治蔵","kana":"よしおかけじゅうたくめいじぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市鹿本町来民字今古閑2032-2","lat":32.996639,"lng":130.726457,"geo_status":"db","era":"明治22頃","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積73㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"43－0160","desc":"主屋正面に東西棟で建つ。土蔵造平屋建、切妻造桟瓦葺で、南面に下屋を差し掛ける。西端の桁行一間部分は南面を開放、北面を両開扉とし、馬車の敷地内への通路となっていた。馬を繋ぐ金物も残るなど、馬屋としての機能を併せ持つ蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011428"},{"id":"00011430","register_sub_id":"101","register_pk":"209267","name":"吉岡家住宅薬医門","kana":"よしおかけじゅうたくやくいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県山鹿市鹿本町来民字今古閑2034","lat":32.996706,"lng":130.726421,"geo_status":"db","era":"明治16頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"43－0162","desc":"主屋正面、明治蔵北西隅に近接して建つ。変形の薬医門形式で、間口二・三メートル。比較的細身の部材を用い、装飾要素も少なく簡素な外観を示す。屋根は切妻造桟瓦葺。両開板戸は塀と意匠を揃え、上部を透いて、たすき桟を入れる。敷地景観を構成する門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011430"},{"id":"00015527","register_sub_id":"101","register_pk":"533542","name":"吉村家住宅主屋","kana":"よしむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目663","lat":32.73725,"lng":130.68261667,"geo_status":"db","era":"明治中期／昭和37年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積306㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0208","desc":"港町川尻に位置し、醸造業を営む商家の主屋。通りより控えて建つ、長大な二階建切妻造桟瓦葺の東西棟で東に内向き、西に表向きの部屋を配す。北西の続き座敷は床・床脇・平書院を備え、欄間彫刻など繊細な意匠を凝らす。近代川尻に隆盛した商家の上質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015527"},{"id":"00015528","register_sub_id":"101","register_pk":"533543","name":"吉村家住宅座敷蔵","kana":"よしむらけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目663","lat":32.73742778,"lng":130.68268889,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0209","desc":"敷地北西隅に位置する家財蔵。土蔵造二階建、切妻造桟瓦葺で、庭を挟んで渡廊下で主屋と接続。外壁は全面漆喰塗で鉢巻を廻し、腰に水切瓦を付す。南面は庇を付して廊下とし、掛子塗戸を開く。内部は各階一室で小屋は登梁形式。商家の屋敷景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015528"},{"id":"00015529","register_sub_id":"101","register_pk":"533544","name":"吉村家住宅道具蔵","kana":"よしむらけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目663","lat":32.73732778,"lng":130.68281111,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0210","desc":"敷地北東に位置する道具蔵兼家財蔵。二階建切妻造平入桟瓦葺で、外壁黒漆喰塗とし、鉢巻を廻し、腰に水切を付す。内部は各階一室で、小屋は登梁形式とし、棟筋の二本の柱は左右に繋梁を架け地棟を受ける特徴的なつくり。重厚な外観で屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015529"},{"id":"00015532","register_sub_id":"101","register_pk":"533547","name":"吉村家住宅西塀","kana":"よしむらけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目663-2","lat":32.73736389,"lng":130.68260833,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造、瓦葺、延長12m","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0213","desc":"主屋と座敷蔵の間に延び、敷地西辺を区画する塀。布基礎上に一・九メートル間隔で立てた鉄筋コンクリート造の柱間に鉱滓煉瓦積で壁を設け、両面モルタル塗仕上とする。屋根は全体が山形に折れた目板瓦を葺く特異な形式。敷地西辺の屋敷構えをつくる重厚な塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015532"},{"id":"00015530","register_sub_id":"101","register_pk":"533545","name":"吉村家住宅西門及び南塀","kana":"よしむらけじゅうたくにしもんおよびみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目660-1他","lat":32.73720556,"lng":130.6825,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"西門 木造、瓦葺、間口1.7m、袖塀付 南塀 木造、瓦葺、総延長15m","structure_material":"西門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0211","desc":"敷地南面西半を画す門と塀。西門は通りから引込んで建つ切妻造平入桟瓦葺の門で、軒先銅板葺とし、門口に引違格子戸と両開板戸を構える。南塀は総延長一五メートル、桟瓦葺で壁は漆喰塗、腰は外側を竪板張、内側を杉皮張。清閑な佇まいをつくる西門及び南塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015530"},{"id":"00015531","register_sub_id":"101","register_pk":"533546","name":"吉村家住宅東門及び東塀","kana":"よしむらけじゅうたくひがしもんおよびひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市南区川尻四丁目660-1","lat":32.73709167,"lng":130.68268889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"東門 木造、瓦葺、間口1.4m、袖塀付 東塀 木造、瓦葺、総延長13m","structure_material":"東門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"43 - 0212","desc":"敷地南正面の東端を画す門と塀。東門は通りから引込んで建つ切妻造平入桟瓦葺の腕木門で、門口に引違格子戸と片開板戸を構える。東門から北へ延びる東塀は延長一三メートルの桟瓦葺の板塀で内外とも竪板張とする。商家の瀟洒な屋敷構えを整える東門及び東塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015531"},{"id":"00016748","register_sub_id":"101","register_pk":"579232","name":"米家住宅主屋","kana":"よねけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.489114,"lng":130.599449,"geo_status":"db","era":"明治33年／昭和前期増築、令和元年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積540㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0232","desc":"球磨川河口に位置する旧廻船問屋の主屋。南面して建つ2階建入母屋造桟瓦葺で、西面中央に入母屋造の式台玄関、南寄りに洋室を突出する。外壁は漆喰塗で二階腰は八角の海鼠壁仕上。南庭に面し１５畳と１４畳の続き座敷を配し、大規模で上質な近代和風の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016748"},{"id":"00016756","register_sub_id":"101","register_pk":"579240","name":"米家住宅北門及び塀","kana":"よねけじゅうたくきたもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642-1","lat":32.489206,"lng":130.599352,"geo_status":"db","era":"明治後期／令和元年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"北門 木造、瓦葺、間口2.3m 塀 木造、瓦葺、総延長53m","structure_material":"北門 木造","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0240","desc":"敷地西面の北端部に位置し、通りから引き込み建つ正門と通り沿いに延びる塀。北門は切妻造平入桟瓦葺の腕木門。塀は半間毎に柱を立て、真壁漆喰塗の腰は八角の海鼠壁。北門両脇を簓子下見板張とする。間口の広い門と長大な塀が、旧家の重厚な屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016756"},{"id":"00016751","register_sub_id":"101","register_pk":"579235","name":"米家住宅五号ノ蔵","kana":"よねけじゅうたくごごうのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.488875,"lng":130.599414,"geo_status":"db","era":"大正3年／令和元年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0235","desc":"主屋の南東に位置する家財蔵。土蔵造2階建切妻造平入桟瓦葺で北面西寄りの戸口に下屋を付す。外壁漆喰塗で北面腰は八角の海鼠壁仕上、通り側は桟瓦風の独特な瓦張とする。各階板敷の一室で小屋組は登梁と束立を併用する。小規模ながらも丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016751"},{"id":"00016755","register_sub_id":"101","register_pk":"579239","name":"米家住宅中門及び塀","kana":"よねけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642-1","lat":32.48908,"lng":130.599284,"geo_status":"db","era":"大正前期／令和元年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"中門 木造、瓦葺、間口2.3m 塀 木造、瓦葺、総延長8.4m","structure_material":"中門 木造","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0239","desc":"主屋と七号ノ蔵の間に位置し、敷地南側の土蔵群への入口に開く門及び塀。西面して建つ中門は切妻造平入桟瓦葺の腕木門で、北に脇門を開く。南に延びる塀は漆喰塗で、腰は外は八角の海鼠壁、内は竪板張。総欅の中門が重厚な塀とともに旧家の屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016755"},{"id":"00016754","register_sub_id":"101","register_pk":"579238","name":"米家住宅長屋門","kana":"よねけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.489149,"lng":130.59928,"geo_status":"db","era":"明治後期／令和元年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積19㎡、西面南塀付","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0238","desc":"敷地西辺の南寄りに位置し、通りに西面して建つ長屋門。平屋建入母屋造桟瓦葺で、北寄りを門口として両開の板扉を吊り、南寄りは一室で畳敷の供待とする。外壁は漆喰塗で腰は八角の海鼠壁仕上、門口廻りは竪板張。通りに面し、旧家の重厚な表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016754"},{"id":"00016753","register_sub_id":"101","register_pk":"579237","name":"米家住宅七号ノ蔵","kana":"よねけじゅうたくななごうのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.489069,"lng":130.599187,"geo_status":"db","era":"大正前期／令和元年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造平屋建、瓦葺、建築面積47㎡","structure_material":"土蔵造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0237","desc":"敷地の南西隅に位置する米蔵。土蔵造平屋建切妻造平入桟瓦葺。外壁は漆喰塗で東面の腰は八角の海鼠壁とする以外は桟瓦風の独特な瓦張。東面の北寄りに庇を付す。内部は板敷の一室で、小屋組は登梁と束立を併用する。角地に建ち、重厚な屋敷構えをつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016753"},{"id":"00016749","register_sub_id":"101","register_pk":"579233","name":"米家住宅離れ","kana":"よねけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.489017,"lng":130.599586,"geo_status":"db","era":"明治33年頃／令和元年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0233","desc":"主屋の南東部に接続する隠居用の離れ。２階建入母屋造桟瓦葺で東に便所を付属する。各階に６畳の続き座敷を配し、北・東面に縁を廻らす。二階の座敷は床と床脇に天袋・違棚を構え、赤松の皮付丸太など用材を吟味した瀟洒なつくり。広大な庭を望む上質な離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016749"},{"id":"00016750","register_sub_id":"101","register_pk":"579234","name":"米家住宅四号ノ蔵","kana":"よねけじゅうたくよんごうのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.488796,"lng":130.599599,"geo_status":"db","era":"文化元年(1804)／令和元年改修","year":1804,"year_source":"db","year_min":1804,"year_max":1804,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0234","desc":"主屋の南東に位置する家財蔵。土蔵造2階建切妻造平入桟瓦葺で、北面に下屋を付す。外壁は漆喰塗仕上、腰は桟瓦風の独特な瓦張。各階板敷の一室で、中央の独立柱で地棟を受け、小屋組は登梁形式とする。下屋に舟を吊るしたと伝え、河口の土地柄を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016750"},{"id":"00016752","register_sub_id":"101","register_pk":"579236","name":"米家住宅六号ノ蔵","kana":"よねけじゅうたくろくごうのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県八代市植柳元町字鳥井前5642","lat":32.488994,"lng":130.599264,"geo_status":"db","era":"大正前期／令和元年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"43 - 0236","desc":"主屋の南に位置する味噌蔵。土蔵造2階建、切妻造平入桟瓦葺で北面に下屋を付す。外壁漆喰塗で北面は軒を持送り、通り側は腰に八角の海鼠壁を高く張る。1階の西は味噌蔵、東は作業場、二階は一室の物置。小屋は登梁と束立の併用。敷地南側の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016752"},{"id":"00010386","register_sub_id":"101","register_pk":"199158","name":"旅館白磯倉庫","kana":"りょかんしらいそそうこ","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県天草市天草町高浜南字御手洗2725-3","lat":32.373373,"lng":129.997681,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"43 - 0129","desc":"本館の西側に南北棟で建つ倉庫。木造二階建、寄棟造桟瓦葺で、東面から北面に吹放しの下屋を付す。一階は土間で二階は板間とし、小屋組はキングポストトラスである。外壁は下見板張で、窓は外側を両開板戸、内側を引分ガラス戸とするなど洋風意匠を加味する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010386"},{"id":"00010385","register_sub_id":"101","register_pk":"199157","name":"旅館白磯離座敷","kana":"りょかんしらいそはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県天草市天草町高浜南字御手洗2725-2","lat":32.37323,"lng":129.997501,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積219㎡","structure_material":"木造平屋一部2階建","registered":"2014.12.19(平成26.12.19)","register_no":"43 - 0128","desc":"本館の南西に建ち、平屋建の主体部は寄棟造桟瓦葺で四周に下屋を廻らす。外壁を下見板張として鎧戸付で縦長の上下窓を並べるなど洋風の要素を見せるが、内部はトコを備えた八畳などを並べる和風座敷とする。本館とともに前庭を囲み、屋敷構えに趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010385"},{"id":"00010384","register_sub_id":"101","register_pk":"199156","name":"旅館白磯本館","kana":"りょかんしらいそほんかん","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県天草市天草町高浜南字御手洗2725-3","lat":32.373303,"lng":129.997845,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺、建築面積456㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"43 - 0127","desc":"実業家赤﨑伝三郎の自邸で敷地奥に南面して建つ。西側の座敷部正面に入母屋屋根を重層させた玄関を構え、東隣にモルタル塗の外壁を石造風に目地切した二階建洋館を並べ、背後の中庭を囲む廊下沿いに各室を配置する。戦前の天草を代表する豪壮な洋館併設住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010384"},{"id":"00006306","register_sub_id":"101","register_pk":"107289","name":"糸永家住宅主屋","kana":"いとながけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市浜脇1-11-15","lat":33.26936438,"lng":131.50880054,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"44 － 0129","desc":"西側道路に面して建つ，平入の町家である。桁行８間，梁間４間半規模で，２戸長屋の形式をもつ。木造２階建，寄棟造，桟瓦葺。それぞれの住戸が６畳広さの表土間をもち，通り土間の形式をもつ。南側住戸の奥に離れが増築され，正面は塗屋造の重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006306"},{"id":"00006597","register_sub_id":"101","register_pk":"107580","name":"糸永家住宅離れ","kana":"いとながけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市浜脇1-11-15","lat":33.269493,"lng":131.508896,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積64㎡、渡廊下付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"44 － 0130","desc":"主屋の東側に建つ。桁行３間，梁間２間で，土蔵造２階建，切妻造，桟瓦葺とする。腰を海鼠壁とし外壁漆喰塗を鉄板で覆い，漆喰塗の鉢巻を廻す。北面に観音開きの土戸を吊り込み，２階北面及び東面に鉄板開戸の窓を開く。規模は小さいが丁寧につくられた蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006597"},{"id":"00003179","register_sub_id":"101","register_pk":"104169","name":"井上家住宅石塀","kana":"いのうえけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.37694602,"lng":130.89286732,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"石造、延長25m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0090","desc":"主屋上手座敷北側にある庭園の東側を区切る石塀で，南端は米蔵に接続する。外側は川で一段低いため玉石積の石垣の上に築く。中央部は一段高く石を積み丸窓を開け，庭園を意識した意匠となっている。敷地の構成要素として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003179"},{"id":"00003176","register_sub_id":"101","register_pk":"104166","name":"井上家住宅米蔵","kana":"いのうえけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.3767485,"lng":130.89287466,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積110㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0087","desc":"土蔵北側にある平屋建，桟瓦葺の土蔵。南側の米蔵との間に川へ至る階段があり，川舟で荷物を運搬したことが窺われる。外観は漆喰塗，腰海鼠瓦張で，内部を壁漆喰仕上，漆喰塗上天井とするのが珍しい。主屋と同時に建設したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003176"},{"id":"00003172","register_sub_id":"101","register_pk":"104162","name":"井上家住宅主屋","kana":"いのうえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.37683982,"lng":130.892609,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積435㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0083","desc":"井上家は日田市北方の鶴河内で農業のほか山林経営や酒造業を営んだ。主屋は２階建，桟瓦葺の巨大な和風住宅で，門を入ったところには屋根を一段切り上げて入母屋の破風を見せ，ペンキを塗ったハーフティンバーの洋風の意匠とし，２階を洋間の応接間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003172"},{"id":"00003175","register_sub_id":"101","register_pk":"104165","name":"井上家住宅土蔵","kana":"いのうえけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.37660017,"lng":130.89266282,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0086","desc":"敷地の南東角にあって酒蔵東に接続する２階建，切妻造，桟瓦葺の土蔵。外観は酒蔵と同様に腰を海鼠瓦張とし，内部は２階は天井を張り，畳を入れて座敷の設えとする。井上家の建築群の中では最も建築年代が古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003175"},{"id":"00003178","register_sub_id":"101","register_pk":"104168","name":"井上家住宅納屋","kana":"いのうえけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.37703602,"lng":130.89250998,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築218㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0089","desc":"敷地北西角に鍵の手に建てられた２階建，桟瓦葺の納屋。内部は物置のほか，牛舎や堆肥小屋に使用される。西側の道路に中央の通用口を開き，外側は漆喰塗籠で腰板壁を張ることから，外観は大壁の長屋門のように見える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003178"},{"id":"00003177","register_sub_id":"101","register_pk":"104167","name":"井上家住宅味噌蔵","kana":"いのうえけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.37701566,"lng":130.89264798,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0088","desc":"主屋下手背後にある２階建，切妻造，桟瓦葺の土蔵。外観は漆喰塗込で腰に板壁を張り，内部は中塗仕上とする。主屋の炊事場に隣接し，自家用味噌醸造用の瓶などが現存する。旧家の内向きの生活を窺わせる施設として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003177"},{"id":"00003173","register_sub_id":"101","register_pk":"104163","name":"井上家住宅門","kana":"いのうえけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.37671684,"lng":130.89240784,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0084","desc":"敷地南側の私道から主屋前庭に至る門で，両側は土塀に接続する。桟瓦葺の四脚門であるが，親柱筋を棟通りから若干前方に寄せた，薬医門風の構造とする。井上家の正式な入口として独立した門を構え，家の格式をあらわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003173"},{"id":"00003181","register_sub_id":"101","register_pk":"104171","name":"岩尾家住宅（旧日本丸製薬所）離れ","kana":"いわおけじゅうたく（きゅうにほんがんせいやくしょ）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市豆田町4-15","lat":33.32740388,"lng":130.93759347,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0092","desc":"主屋背後に２階建の渡り廊下を介して接続する２階建，桟瓦葺の便所と湯殿，座敷からなる建物。便所の外観は黒磨漆喰，内部にも大理石や大理石を擬した漆喰壁，大判の鏡を壁にはめ込むなど贅を凝らす。座敷も小規模ながら本格的なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003181"},{"id":"00008218","register_sub_id":"101","register_pk":"132743","name":"植木家住宅主屋","kana":"うえきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子中町349","lat":33.24258324,"lng":131.59378158,"geo_status":"db","era":"安政元年（1854）／平成15年改修","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造2階建、瓦葺、建築面積134㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0171","desc":"通りに北面して建つ町家。桁行１５ｍ梁間９．８ｍの木造２階建で、入母屋造桟瓦葺、妻入とする。１階に出格子を構え、彫刻入りの大きな持送りを付けて、下屋を持ち出し、下屋両袖は漆喰で塗り込めるという、特徴的な構えになる。市内に残る数少ない近世商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008218"},{"id":"00008219","register_sub_id":"101","register_pk":"132744","name":"植木家住宅離れ","kana":"うえきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県大分市王子中町349","lat":33.24234792,"lng":131.59387795,"geo_status":"db","era":"昭和4年／平成12年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0172","desc":"主屋の南方に東西棟で建つ。入母屋造桟瓦葺で下屋庇をまわす。桁行８．９ｍ梁間６．１ｍの木造平屋建、東面に便所等を付設。トコ、棚、書院を構える八畳と次の間を東西に並べ、三方に縁をまわす。座敷飾りや繊細な障子などに洗練された意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008219"},{"id":"00008220","register_sub_id":"101","register_pk":"132745","name":"植木家住宅離れ控えの間","kana":"うえきけじゅうたくはなれひかえのま","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県大分市王子中町349","lat":33.24238154,"lng":131.59380624,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡、渡廊下付","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0173","desc":"離れに直角に付き、主屋と渡廊下で繋がる。入母屋造桟瓦葺で、庇をまわす。トコや違棚、平書院を付ける六畳一室で、その三方に縁を付ける。下屋庇の軒は吹き寄せの竹垂木と丸太垂木を交互に並べ、数寄屋風の意匠を見せる。良材を使い、丁寧な施工がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008220"},{"id":"00004870","register_sub_id":"101","register_pk":"105860","name":"荻本家住宅主屋","kana":"おぎもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市坂ノ市中央2-2-15","lat":33.23505869,"lng":131.74581107,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積244㎡","structure_material":"木造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"44 － 0102","desc":"大分市東部，丹生川右岸の河口近くに位置し，布石積で地上げされた敷地に建つ。桁行７間梁行５間半規模，入母屋造，桟瓦葺の木造平屋建で，西南に入母屋造の８畳奥座敷を，北東に寄棟造の釜屋を突き出す。東南隅に式台玄関を置くなど格式あるつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004870"},{"id":"00000506","register_sub_id":"101","register_pk":"101496","name":"萱島家住宅主屋","kana":"かやしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52513122,"lng":131.72591476,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建，瓦葺，建築面積228㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0032","desc":"醸造所の敷地のほぼ中央に建つ木造２階建，寄棟造，桟瓦葺の主屋。１階は北端部を開放とし，北側に隣接する酒造事務所と繋げて一体的な利用を図る。２階正面は，前面ガラス窓として開放的な造りとする。規模の大きな萱島酒造の主屋として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000506"},{"id":"00000507","register_sub_id":"101","register_pk":"101497","name":"萱島家住宅離れ","kana":"かやしまけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52500152,"lng":131.72598579,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積88㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0033","desc":"主屋の東南に近接して建つ木造平屋建，入母屋造の建物。軒廻りや妻壁を漆喰仕上げとし，南面及び西面に庇を付加して広縁をとる。内部の造作は丁寧で，全体として保存も良い。明治期の離れ座敷の好例であり，南面の庭園と一体的に構成されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000507"},{"id":"00007327","register_sub_id":"101","register_pk":"108309","name":"旧稲葉家別邸御居間","kana":"きゅういなばけべっていおんいま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲6-6","lat":33.121456,"lng":131.79937675,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0142","desc":"大書院の東方に畳廊下を介して繋がる。東西棟の寄棟造桟瓦葺で、南・東・北面に庇を付ける。田の字型平面で、東北にトコと違棚を構える主室、その南に二ノ間を配し、三方に榑縁をまわす。内法上に引違明障子をたてるなど、明るく穏やかな居室空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007327"},{"id":"00007330","register_sub_id":"101","register_pk":"108312","name":"旧稲葉家別邸御門","kana":"きゅういなばけべっていごもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲6-6","lat":33.121323,"lng":131.799057,"geo_status":"db","era":"明治35頃／平成元改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0145","desc":"大書院の正面、通りに南面して建つ。間口２．７ｍと規模の大きい腕木門で、両脇に潜戸を設け、背面には控柱を建てる。腕木先に舟肘木を置き、軒桁を支持する。軒は一軒疎垂木。冠木と棟木間に連子を組む。旧藩主の別邸としての風格のある正面構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007330"},{"id":"00007331","register_sub_id":"101","register_pk":"108313","name":"旧稲葉家別邸外塀及び東門","kana":"きゅういなばけべっていそとべいおよびひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲6-6","lat":33.1212007,"lng":131.79928111,"geo_status":"db","era":"明治35頃／平成2改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"塀 土塀、延長45m 門 木造、瓦葺、間口2.3m","structure_material":"塀 土塀","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0146","desc":"御門潜戸脇から折れ曲がり、東西に延びる延長４５ｍの塀で、東端に通用口である東門を構える。塀は地元産の凝灰岩を積み、土台を置き、柱を建て、壁は漆喰仕上げで外側に腰下見板を張る。東門は間口２．３ｍ、両開板戸をたてる。伝統的な街路景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007331"},{"id":"00007326","register_sub_id":"101","register_pk":"108308","name":"旧稲葉家別邸大書院","kana":"きゅういなばけべっていだいしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲6-6","lat":33.121506,"lng":131.799149,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0141","desc":"敷地の中央に南面して建つ。入母屋造妻入桟瓦葺で、側・背面に庇をまわし、正面に大振りの入母屋造玄関を付ける。内部はトコとトコ脇を構える上ノ間と十八畳半の二ノ間を南北に並べ、南面に畳廊下、三方に縁をまわす。公的な接客空間の面影を残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007326"},{"id":"00007328","register_sub_id":"101","register_pk":"108310","name":"旧稲葉家別邸台所","kana":"きゅういなばけべっていだいどころ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲6-6","lat":33.12138,"lng":131.799271,"geo_status":"db","era":"明治35頃／平成2改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0143","desc":"御居間の南に位置する。桁行８．０ｍ梁間８．０ｍ規模の木造２階建。南北棟の入母屋造桟瓦葺で、三方に庇をまわし、東・南面は吹き放す。壁は漆喰仕上げ。内部は南に土間、北半を床上部とし、一部畳敷の板間とする。土間東半部は吹抜け、他は根太天井である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007328"},{"id":"00007329","register_sub_id":"101","register_pk":"108311","name":"旧稲葉家別邸土蔵","kana":"きゅういなばけべっていどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲6-6","lat":33.12127261,"lng":131.79922556,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0144","desc":"台所の南に、東西棟で北面して建つ。切妻造桟瓦葺。基礎は切石積、壁は漆喰仕上げとする。桁行６．９ｍ梁間４．１ｍ規模で、中央やや西寄りに壁を設けて２室に分け、西室は２階を設ける。それぞれに出入口を設け、東の庇を深く大きくし、外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007329"},{"id":"00015111","register_sub_id":"101","register_pk":"529389","name":"旧志手家住宅(カテリーナ古楽器研究所)主屋","kana":"きゅうしてけじゅうたく（かてりーなこがっきけんきゅうじょ）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県杵築市山香町大字野原字台428","lat":33.43943333,"lng":131.49510556,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"44 - 0235","desc":"八坂川北岸の小高い丘陵に位置する旧家の主屋。敷地に南面して建つ二階建入母屋造平入桟瓦葺で西・北面の軒を漆喰で塗込める。南中央に式台を構え、西に土間、東に二列六室並べ、北東は床と神棚を備えた座敷とする。田園の中に点景をなす重厚で大規模な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015111"},{"id":"00002106","register_sub_id":"101","register_pk":"103096","name":"国見ふるさと展示館休憩所（旧有永邸馬屋）","kana":"くにみふるさとてんじかんきゅうけいじょ（きゅうありながていうまや）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県国東市国見町岐部536","lat":33.66542001,"lng":131.62472945,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"44 － 0049","desc":"主屋の北方，通用門から石柱の東門へと通り抜ける通路を隔てて南面して建つ。東西棟，切妻造，桟瓦葺の細長い建屋で，南と西の２面に吹放ちの土間庇を廻す。現在は，西方を便所，中程を物産品販売所，東方をレストランに改造して積極的な活用が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002106"},{"id":"00002104","register_sub_id":"101","register_pk":"103094","name":"国見ふるさと展示館研修所（旧有永邸離れ）","kana":"くにみふるさとてんじかんけんしゅうじょ（きゅうありながていはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県国東市国見町岐部536","lat":33.66511563,"lng":131.62500473,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"44 － 0047","desc":"主屋の東南方に位置し，主屋南東端の客用風呂場から渡り廊下により連絡する。木造２階建，南北棟の寄棟造，桟瓦葺の離れで，亀甲積石垣を基礎として建ち，階下は土間とし，階上に６畳・１０畳・８畳の３室を設け，研修室・集会室等に利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002104"},{"id":"00002103","register_sub_id":"101","register_pk":"103093","name":"国見ふるさと展示館資料館（旧有永邸主屋）","kana":"くにみふるさとてんじかんしりょうかん（きゅうありながていしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県国東市国見町岐部536","lat":33.66523732,"lng":131.62479606,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積343㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"44 － 0046","desc":"幕末期の惣代庄屋を勤めた下岐部村の有永三郎の屋敷で，主屋は敷地のほぼ中央に西面して建つ。木造２階建，緩くムクリをつけた豪放な入母屋造で，四周に庇を廻し，内部は６間取形式をとる。階下は資料館として，階上はギャラリーとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002103"},{"id":"00002105","register_sub_id":"101","register_pk":"103095","name":"国見ふるさと展示館展示場（旧有永邸蔵）","kana":"くにみふるさとてんじかんてんじじょう（きゅうありながていくら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県国東市国見町岐部536","lat":33.66526588,"lng":131.62494757,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"44 － 0048","desc":"主屋のシモテ，通土間部の東方に位置し，敷地境に積まれた低い石積擁壁の上に建つ。木造２階建，南北棟の寄棟造，桟瓦葺で，階下は収蔵庫，階上は展示室として利用が図られている。階上は東面の開口部から判断して居室であったと推測される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002105"},{"id":"00000321","register_sub_id":"101","register_pk":"101311","name":"小手川家住宅","kana":"こてがわけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字浜町538","lat":33.12040094,"lng":131.79717346,"geo_status":"db","era":"慶応元頃","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建，瓦葺，建築面積128㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"44 － 0017","desc":"酒造業を営む家の離れとして母屋と同時期に建設されたと伝える。母屋の東に隣接し，現在は東半部を住居，西半部を野上弥生子文学記念館とする。せがい軒で正面に格子を入れたこの地方によくみられる町家のひとつで，漆喰塗りの母屋と好対照の意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000321"},{"id":"00006074","register_sub_id":"101","register_pk":"107059","name":"佐藤家住宅旧店舗兼主屋","kana":"さとうけじゅうたくきゅうてんぽけんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町102-2他","lat":32.9667549,"lng":131.3952602,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0126","desc":"敷地の南東隅の角に建つ。桁行９間，梁間５間の規模で，木造平屋建，切妻造，桟瓦葺，一部に２階を設ける。元は前土間及び通り土間をもつ形式で，後方に座敷等和室３室を並べる。２階正面を漆喰塗とする規模の大きな町家で，町並み景観のなかで存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006074"},{"id":"00006072","register_sub_id":"101","register_pk":"107057","name":"佐藤家住宅旧味噌蔵","kana":"さとうけじゅうたくきゅうみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町102-2他","lat":32.96673467,"lng":131.39537952,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0127","desc":"道路に面して，主屋の北側に接して建つ。桁行３間半，梁間３間で，木造２階建，切妻造，桟瓦葺とする。道路側に下屋をつくり，両脇の建物を連絡する通路とする。周囲に土蔵の漆喰塗の壁を見せ，変化ある町並みの景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006072"},{"id":"00006073","register_sub_id":"101","register_pk":"107058","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町102-2他","lat":32.96671019,"lng":131.39547438,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積184㎡","structure_material":"木造平屋一部2階建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0125","desc":"東側道路に面して，敷地の北端に建つ。桁行５間半，梁間５間半で，木造２階建，切妻造，桟瓦葺とする。前土間をもつ町家の形式で，１階，２階に和室及び板の間を配す。２階及び敷地境の北面の壁を漆喰塗とし，２階軒を出桁造とする比較的規模の大きな町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006073"},{"id":"00006071","register_sub_id":"101","register_pk":"107056","name":"佐藤家住宅土蔵","kana":"さとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町102-2他","lat":32.96657828,"lng":131.39536167,"geo_status":"db","era":"明治12頃","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0128","desc":"主屋の西側後方に建ち，桁行３間，梁間２間半で，土蔵造２階建，切妻造，桟瓦葺とする。１階東側１箇所，２階両妻側にそれぞれ２箇所に窓を開き，南妻側に戸口を開く。壁面を漆喰塗とし，小規模なつくりとする。商家の敷地景観を今日に伝え，貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006071"},{"id":"00013472","register_sub_id":"101","register_pk":"368568","name":"佐藤家住宅離れ","kana":"さとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県速見郡日出町大字大神字深江5436","lat":33.35425833,"lng":131.58339444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"44 － 0232","desc":"大神漁港の入江に面した敷地で、通りに北面して建つ。木造平屋建、寄棟造桟瓦葺で、四周に下屋を廻らせ、正面に切妻屋根の玄関を付す。北から板間と座敷二室を並べ、東と南に縁を配す。磨き丸太の軒桁や垂木等、数寄屋意匠を基調とした瀟洒な造りの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013472"},{"id":"00000280","register_sub_id":"101","register_pk":"101270","name":"山海荘主屋","kana":"さんかいそうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵70-14、30","lat":33.12590054,"lng":131.80261189,"geo_status":"db","era":"江戸後期／明治末年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建，瓦葺，建築面積202㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"44 － 0010","desc":"臼杵城にあった御殿を明治末年に現在地に移築したと伝える。むくりの付いた入母屋屋根に庇を設け屋根を二重にする外観や側廻りを開放的な扱いとする平面構成等に，江戸時代の書院造りの系譜を引く建物としての特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000280"},{"id":"00003773","register_sub_id":"101","register_pk":"104763","name":"塩屋中蔵","kana":"しおやなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県竹田市大字竹田町字本町503","lat":32.96794149,"lng":131.39213538,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"44 － 0099","desc":"細長い敷地のほぼ中央，主屋後方に建つ。切妻造，桟瓦葺，平入の２階建土蔵で，外壁は軒裏まで漆喰塗とし，２階の小窓には鉄格子を入れる。内部は桁行中央の漆喰壁で２分され，主屋側が座敷，残りが倉庫になる。主屋と連続して商家の佇まいを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003773"},{"id":"00003774","register_sub_id":"101","register_pk":"104764","name":"塩屋古蔵","kana":"しおやふるぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県竹田市大字竹田町字本町503","lat":32.96789757,"lng":131.39211335,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"44 － 0100","desc":"敷地最奥，中蔵後方に建つ。桁行７．５ｍ，梁間５．９ｍで，切妻造，桟瓦葺，平入の２階建土蔵。外壁は漆喰塗で，軒裏から破風まで塗籠める。敷地側の１階戸口は漆喰扉を吊るが，周囲を鳥居型に縁取る。丁寧なつくりの土蔵で，屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003774"},{"id":"00002107","register_sub_id":"101","register_pk":"103097","name":"重光家住宅主屋","kana":"しげみつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県国東市国見町向田1911","lat":33.6486268,"lng":131.67149256,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"44 － 0050","desc":"国見町東端に位置する向田地区に建つ。木造平屋建，入母屋造の主体部の南西部から土間玄関・帳場を南方に突出させ，入母屋破風を重ねた重厚な構えをとり，北西隅の台所には明取りを兼ねた特徴ある宝形屋根を載せる。設計は国東町出身の吉武東里。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002107"},{"id":"00005388","register_sub_id":"101","register_pk":"106376","name":"高橋家住宅主屋","kana":"たかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字掛町527-1","lat":33.12112234,"lng":131.79689714,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"44 － 0115","desc":"市街地西側で，臼杵川に平行する通りに東面して建つ町家建築。地元の社寺建設を多数手掛けた東秀蔵の作品。間口７．８ｍ，奥行８．９ｍ規模の切妻造，平入とし，出桁造の正面には下屋庇を張り出し，格子窓を設けるなど，町並み景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005388"},{"id":"00002866","register_sub_id":"101","register_pk":"103856","name":"多田家住宅御成門","kana":"ただけじゅうたくおなりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後大野市三重町市場1308-1","lat":32.97885672,"lng":131.58217032,"geo_status":"db","era":"元治元","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2002.06.25(平成14.06.25)","register_no":"44 － 0079","desc":"御成屋敷の式台玄関の正面に建つ。一間一戸薬医門で，勾配が緩く反りの強い屋根が特徴。御成屋敷とともに臼杵藩主を迎えるために建てられた建築であり，大庄屋屋敷としての格式を示すとともに，屋敷地の景観に欠くことのできないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002866"},{"id":"00002865","register_sub_id":"101","register_pk":"103855","name":"多田家住宅御成屋敷","kana":"ただけじゅうたくおなりやしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後大野市三重町市場1308-1","lat":32.97889198,"lng":131.58204964,"geo_status":"db","era":"元治1","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造2階建、瓦葺、建築面積166㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"44 － 0078","desc":"旧臼杵藩大庄屋の居宅で，藩主を迎えるために建てられた。明治期に入っては大野郡役所庁舎が建設されるまでの間郡役所としても用いられた。平入の式台玄関から次の間，座敷を連続させ，三方に縁を廻らす。内部には御成屋敷にふさわしい意匠を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002865"},{"id":"00002868","register_sub_id":"101","register_pk":"103858","name":"多田家住宅蔵","kana":"ただけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後大野市三重町市場1308-1","lat":32.97912331,"lng":131.58195581,"geo_status":"db","era":"元治元","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"44 － 0081","desc":"主屋の背面側に建つ土蔵で，当初は米蔵として用いられていた。石積の基礎の上に設けて床を上げ，腰部はなまこ壁とし，軒まで塗籠とする。立ちが高いのが特徴で，主奥側に入口を２カ所設けてそれぞれ庇をかけている。大庄屋の屋敷の格を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002868"},{"id":"00002867","register_sub_id":"101","register_pk":"103857","name":"多田家住宅主屋","kana":"ただけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後大野市三重町市場1308-1","lat":32.97903815,"lng":131.58209676,"geo_status":"db","era":"元治元","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"44 － 0080","desc":"御成屋敷東側に接して建つ南北棟の居宅。棟札より元治元年の建設であることが知られる。御成屋敷の玄関に並行して妻入の玄関を開き，全体でＬ字型平面をなして庭を囲んでいる。屋根面の起りなど御成屋敷と意匠面において差を付けていることが注目される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002867"},{"id":"00002325","register_sub_id":"101","register_pk":"103315","name":"聴潮閣主屋","kana":"ちょうちょうかくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県別府市青山町3107-5","lat":33.27775734,"lng":131.4909233,"geo_status":"db","era":"昭和4／平成元移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦一部銅板葺、建築面積148㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0051","desc":"別府政財界の実力者高橋欽哉によって浜脇の地に建てられた住居兼迎賓館。入母屋造平屋建の玄関棟と，入母屋造２階建の座敷棟より成る。座敷棟の階下は１０畳２室，階上は３室を１列に並べ，正面と背面の両側に廊下を付ける。良材を用いた品格ある造りに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002325"},{"id":"00002326","register_sub_id":"101","register_pk":"103316","name":"聴潮閣洋館","kana":"ちょうちょうかくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県別府市青山町3107-5","lat":33.27774701,"lng":131.49100348,"geo_status":"db","era":"昭和4／平成元移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0052","desc":"玄関棟の左手から正面前方に突き出した洋館。外観は陸屋根状につくり，内部は２室の続き間として，大理石のマントルピース，ベイウィンドー，ステインドグラスの窓など洋風インテリアの主要要素を備える。大工棟梁は主屋とも平野介治と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002326"},{"id":"00000279","register_sub_id":"101","register_pk":"101269","name":"野上弥生子成城の家","kana":"のがみやえこせいじょうのいえ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県臼杵市大字臼杵70-15","lat":33.12591239,"lng":131.80230913,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建，瓦葺，建築面積74㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"44 － 0009","desc":"臼杵生まれの作家野上弥生子が東京の成城で住んだ家を現在地に移築したもの。スペイン瓦で葺いた急勾配の屋根やモルタル仕上げの外壁等を持つ洋風の外観に昭和初期の東京における郊外住宅の特徴がよく表れている。特に円形のサンルームに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000279"},{"id":"00002339","register_sub_id":"101","register_pk":"103329","name":"久恒家住宅裏門","kana":"ひさつねけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.591022,"lng":131.18436486,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、瓦葺、間口2m","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0065","desc":"久恒家の屋敷地はほぼ正方形で，約１０００坪の広さを持つ。敷地西面のほぼ中央にある裏門は，小規模な１間１戸の棟門で，外側に石階二段を設け，左右に煉瓦塀が延びる。疎垂木の軒，照明を考慮した小壁板など，簡素であるが，堅実な細部を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002339"},{"id":"00002338","register_sub_id":"101","register_pk":"103328","name":"久恒家住宅煙突","kana":"ひさつねけじゅうたくえんとつ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.590984,"lng":131.184677,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造、高さ5.0m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0064","desc":"居住棟西面の張出部分と東蔵とに挟まれた位置にある。平面は１辺約０．９メートルの方形で，高さは約４メートル。壁体は鉱滓煉瓦積で，基礎部を直に立ち上げ，そこから頂部に向かって先細りとなる。居住棟の風呂場用のもので，近代の生活を伺い知る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002338"},{"id":"00002329","register_sub_id":"101","register_pk":"103319","name":"久恒家住宅奥座敷","kana":"ひさつねけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.590851,"lng":131.184555,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0055","desc":"奥座敷の西側に建つ。平屋建で，東西棟の入母屋造の屋根を高く架け，西面には一段低く入母屋造屋根を設け，北側にも入母屋造の角屋が延びる。客間棟や奥座敷とともに京都の宮大工が手がけたと伝え，近代の書院造として洗練された質の高さが随所に伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002329"},{"id":"00002335","register_sub_id":"101","register_pk":"103325","name":"久恒家住宅オンドル部屋","kana":"ひさつねけじゅうたくおんどるべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59111876,"lng":131.1846708,"geo_status":"db","era":"昭和20頃","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0061","desc":"屋敷の北面，東側物置と西側米蔵の間に建てられた。オンドルを採り入れた離れ的な建物で，規模は小さい。切妻造・桟瓦葺で，西半は６畳大で浅い床付の座敷とし，東半は玄関になり，棟をずらして雁行風の外観をつくる。屋敷後方の存在感のある付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002335"},{"id":"00002340","register_sub_id":"101","register_pk":"103330","name":"久恒家住宅北塀","kana":"ひさつねけじゅうたくきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59116657,"lng":131.18460337,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造、延長53m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0066","desc":"広大な久恒家の屋敷の北西隅を画する煉瓦塀。裏門北端から北に延び，東に折れて米蔵東端まで，総延長約３７メートル。御影石の瘤出仕上げの切石積基礎に横長の地覆石を廻し，煉瓦はイギリス積，上部を笠石で覆う。屋敷構に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002340"},{"id":"00002328","register_sub_id":"101","register_pk":"103318","name":"久恒家住宅客間棟","kana":"ひさつねけじゅうたくきゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.590813,"lng":131.184723,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0054","desc":"敷地のほぼ中央に建つ平屋建の建物。Ｌ字型の棟を上げて入母屋造の妻面を南と東につくり，東妻面の下に入母屋造玄関を設け，複雑な屋根を構成する。檜や欅の良材や銘木を用い，丁寧な仕事で仕上げた書院造。近代和風らしく室内が高く，高窓も多用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002328"},{"id":"00002337","register_sub_id":"101","register_pk":"103327","name":"久恒家住宅給水塔","kana":"ひさつねけじゅうたくきゅうすいとう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.591026,"lng":131.184677,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造、高さ7.6m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0063","desc":"東蔵の北面にある。平面は１辺約１．３メートルの方形で，高さは約５メートル。壁体は鉱滓煉瓦の１枚積で，上部の約４分の１をモルタル塗とし，水槽を設ける。頂部には銅板葺の切妻造屋根を架ける。大正期における住環境を物語る数少ない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002337"},{"id":"00002330","register_sub_id":"101","register_pk":"103320","name":"久恒家住宅居住棟","kana":"ひさつねけじゅうたくきょじゅうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59097455,"lng":131.18477521,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積211㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0056","desc":"久恒家は炭鉱経営に成功し，後に貴族院議員となった久恒貞雄氏が建設した。居住棟は屋敷北東よりに建ち，南北棟，入母屋造・桟瓦葺で，四周に下屋を廻す。北側に玄関，南側には銘木を用いた床・付書院をもつ座敷を配する。細部は近代的な造形で纏めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002330"},{"id":"00002334","register_sub_id":"101","register_pk":"103324","name":"久恒家住宅米蔵","kana":"ひさつねけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59113231,"lng":131.184464,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積175㎡","structure_material":"煉瓦造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0060","desc":"屋敷の北西隅にある細長い蔵。東西棟，切妻造・桟瓦葺で，南面に吹放し庇を設ける。小屋組はキングポストトラス，外壁はモルタル塗で，東・北・西の各面に鉄格子入の高窓をつける。豪壮な屋敷に相応しい巨大な蔵で，地域の景観のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002334"},{"id":"00002327","register_sub_id":"101","register_pk":"103317","name":"久恒家住宅正門","kana":"ひさつねけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.590763,"lng":131.184937,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、瓦葺、間口3.0m、北側煉瓦塀附属","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0053","desc":"久恒家は中津市の南郊に所在する邸宅である。ほぼ正方形敷地の東面にある正門は１間１戸の棟門で，背面に控柱を設け，両脇に通用口が付き，左右に煉瓦塀が延びる。軒は疎垂木・木舞打，桟瓦葺屋根をあげる。良質の欅材を使った豪壮なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002327"},{"id":"00002331","register_sub_id":"101","register_pk":"103321","name":"久恒家住宅長屋門","kana":"ひさつねけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.591007,"lng":131.184952,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0057","desc":"長屋門は正門と同じく正方形敷地の東面，北側にある。東を正面とした南北棟，寄棟造・桟瓦葺の細長い建物で，北端が幅２間分の広い通用口，残りは洋風の事務室とする。真壁造で，正面と北側面は煉瓦塀と対照的な白漆喰塗とし，屋敷東側の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002331"},{"id":"00002333","register_sub_id":"101","register_pk":"103323","name":"久恒家住宅西蔵","kana":"ひさつねけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59098166,"lng":131.184494,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積37㎡","structure_material":"煉瓦造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0059","desc":"奥座敷の北西にある木造２階建，寄棟造・桟瓦葺の倉庫建築で，外壁はコンクリート打ち放しのようなモルタル塗。奥座敷と繋がる南面１階を戸口とし，北面２階に窓を設ける。開口部は鉄製の頑丈な両開扉とするなど，防火性能を重視したつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002333"},{"id":"00002332","register_sub_id":"101","register_pk":"103322","name":"久恒家住宅東蔵","kana":"ひさつねけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59102131,"lng":131.18471752,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造及び煉瓦造2階建、瓦葺、建築面積32㎡","structure_material":"木造及び煉瓦造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0058","desc":"居住棟北西にある切妻造・桟瓦葺の倉庫建築。煉瓦造であるが，外壁は漆喰塗とモルタル塗を併用する。１階が収蔵庫，２階が洋風座敷で，下に半地下倉庫をもつ。居住棟側の南面１階に観音開扉をつけ，北面東端に地下入口を設ける。もとは３階望楼を備えていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002332"},{"id":"00002341","register_sub_id":"101","register_pk":"103331","name":"久恒家住宅南塀","kana":"ひさつねけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59069021,"lng":131.18452975,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造、延長117m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0067","desc":"屋敷南面，東面と西面の南半を画する煉瓦塀。東側の物置南端から南に延び，南面前面を経て北に折れ，裏門南端まで，総延長約１１６メートル。御影石の切石積基礎で地覆石を廻し，煉瓦はイギリス積，上部を笠石で覆う。北塀と同じく，屋敷構に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002341"},{"id":"00002336","register_sub_id":"101","register_pk":"103326","name":"久恒家住宅物置","kana":"ひさつねけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字上宮永3-1","lat":33.59110776,"lng":131.18479828,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積32㎡","structure_material":"煉瓦造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0062","desc":"屋敷北面の中央にあり，様々な道具類や雑品を収納する。南北棟，切妻造・鉄板葺の細長い建物で，西側を一段高くする。壁体は鉱滓煉瓦を１枚積のイギリス積で，上部に桁を巡らして丸太状の梁を受け，棟束を立てる。北面は煉瓦塀を用い，通用口を開いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002336"},{"id":"00011603","register_sub_id":"101","register_pk":"210555","name":"平田家住宅主屋","kana":"ひらたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県中津市耶馬溪町大字平田字川原田1062","lat":33.47106389,"lng":131.145185,"geo_status":"db","era":"明治中期／大正12年頃増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部3階建、瓦葺、建築面積415㎡","structure_material":"木造平屋一部3階建","registered":"2017.05.02(平成29.05.02)","register_no":"44-0223","desc":"名勝耶馬渓を望む地に構える。木造三階建、入母屋造、本瓦葺で、東面して建つ。北半を土間、南半を四列に部屋を配す大規模な主屋で、床、棚、付書院を備えた奥座敷や唐破風の表玄関など、高い格式を示す。三階は、広縁を廻らし眺望を意識した造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011603"},{"id":"00011604","register_sub_id":"101","register_pk":"210556","name":"平田家住宅新座敷","kana":"ひらたけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市耶馬溪町大字平田字川原田1062","lat":33.47095306,"lng":131.14506389,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"44-0224","desc":"主屋の南東に玄関を介して接続する。木造平屋建、入母屋造本瓦葺で、軒先を銅板葺とする。座敷を二間を東西に配し、縁を廻らす。床柱に鉄刀木を用い、欄間彫刻も丁寧な造りの上質な近代和風建築。付属する茶室と共に、大正期における住宅の様相を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011604"},{"id":"00005063","register_sub_id":"101","register_pk":"106053","name":"帆足家分家住宅（松石不老館）井戸上屋","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）いどうわや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15265538,"lng":131.6573268,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、建築面積8.8㎡","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0108","desc":"湯殿の西側に東西棟で建つ。桁行２間，梁間１間半の規模で，切石積みの基壇の上に四方に柱を立て，切妻造，桟瓦葺とする。中央の井戸は切石を長方形の井桁に組む。南北の両側に石階段を設ける。規模の大きな井戸上屋で，往時の生活を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005063"},{"id":"00005066","register_sub_id":"101","register_pk":"106056","name":"帆足家分家住宅（松石不老館）裏二階","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）うらにかい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15261576,"lng":131.65726031,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0111","desc":"敷地南西隅に建ち，桁行３間半，梁間２間の規模で，西端に桁行３間半梁間３間の裏木戸の建物を直交して，裏二階東側は寄棟，裏木戸の建物は切妻造とし，共に桟瓦葺，木造２階建である。裏木戸は中央に１間幅の観音開きの木戸口を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005066"},{"id":"00005064","register_sub_id":"101","register_pk":"106054","name":"帆足家分家住宅（松石不老館）穀物蔵","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）こくもつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15273293,"lng":131.65724669,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積93㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0109","desc":"敷地西端の敷地境に南北棟で東面して建ち，桁行７間，梁間３間の規模で，切妻造，桟瓦葺，土蔵造２階建，東面に引戸口２箇所を設け，東面全長に吹き放ちの下屋を付属する。切石積みの上に建ち，床を高くしている。当家で最も大きな蔵で，豪壮な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005064"},{"id":"00005061","register_sub_id":"101","register_pk":"106051","name":"帆足家分家住宅（松石不老館）質蔵","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）しちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4363","lat":33.15286448,"lng":131.6575589,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積41㎡、門及び塀付","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0106","desc":"主屋北側敷地境に東西棟で，主屋北側の庭の一角に建つ。桁行５間，梁間２間半の規模で，切妻造，桟瓦葺，土蔵造２階建。切石積みの上に建ち，南側正面腰を海鼠壁とし，引戸を開き，上部に庇を付け，石階段を設ける。南西隅より桟瓦屋根の板塀及び門を連続させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005061"},{"id":"00005058","register_sub_id":"101","register_pk":"106048","name":"帆足家分家住宅（松石不老館）主屋","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15261893,"lng":131.65755817,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0103","desc":"敷地東側の通りに面して南北棟で建つ。桁行８間半，梁間６間の規模で，入母屋造，桟瓦葺，木造２階建。通り土間をもつ商家建築の形式をとり，北側に座敷や次の間などをとり接客空間とする。特に接客部分の各部屋の意匠は優れ，近代の大工技術の高さが窺え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005058"},{"id":"00005059","register_sub_id":"101","register_pk":"106049","name":"帆足家分家住宅（松石不老館）新座敷","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）しんざしき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361、4363","lat":33.15271404,"lng":131.65742976,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積64㎡、門及び塀付","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0104","desc":"主屋の西側北寄りに東西棟で建つ。桁行５間，梁間３間の規模で，寄棟造，桟瓦葺，木造平屋建である。中央に８畳間の座敷をとり，南側に広縁をとり中庭を望む。南西隅より南に板塀を延ばし，門を設け，更に湯殿まで板塀を延ばす。門及び塀は桟瓦屋根を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005059"},{"id":"00005060","register_sub_id":"101","register_pk":"106050","name":"帆足家分家住宅（松石不老館）道具蔵","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）どうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4363","lat":33.15290562,"lng":131.65744404,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0105","desc":"主屋北西の敷地境に東西棟で建つ。桁行５間，梁間２間の規模。切妻造，桟瓦葺，土蔵造２階建。切石積みの上に建ち，南側正面腰を海鼠壁とし，引戸を開き，上部に庇を付け，石階段を設ける。正面以外には水切り瓦を一列付け，２階正面に鉄扉片開き窓２つを開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005060"},{"id":"00005068","register_sub_id":"101","register_pk":"106058","name":"帆足家分家住宅（松石不老館）塀","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）へい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15275803,"lng":131.65772715,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長14m、庭門付","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0113","desc":"敷地東辺の北寄りの道路境の塀で，長さ１３．７ｍ。切石積みの上に建ち，腰を下見板張りとし，上部を真壁造，漆喰塗りとし，２箇所に格子窓を開け，桟瓦葺屋根とする。南端に庭門を棟を直角にして続ける。袖壁をもつ棟門で間口１．８ｍである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005068"},{"id":"00005065","register_sub_id":"101","register_pk":"106055","name":"帆足家分家住宅（松石不老館）味噌蔵","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）みそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4362","lat":33.15285193,"lng":131.65728007,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0110","desc":"穀物蔵の北側に連続して南北棟で建ち，桁行５間，梁間３間の規模，切妻造，桟瓦葺，木造平屋建。東面に下屋を葺き下ろし，下屋北側２間半分を壁で囲み室内に取り込む。切石積みの上に建ち，床を上げ，真壁構造とするが，西面と北面を板張りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005065"},{"id":"00005067","register_sub_id":"101","register_pk":"106057","name":"帆足家分家住宅（松石不老館）門","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15251045,"lng":131.65757412,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0112","desc":"敷地南東隅に道路からやや退いた位置に東面して建ち，間口は２．７ｍで，棟門の形式をとり，桟瓦葺，木造で，両脇に塀を続け，門脇に潜戸を開く。塀は腰を下見板張り，上部を漆喰塗りとし，桟瓦葺屋根とする。主屋脇に位置し，重厚な門構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005067"},{"id":"00005062","register_sub_id":"101","register_pk":"106052","name":"帆足家分家住宅（松石不老館）湯殿及び風呂","kana":"ほあしけぶんけじゅうたく（しょうせきふろうかん）ゆどのおよびふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市大字中戸次4361","lat":33.15261331,"lng":131.65737352,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0107","desc":"主屋西側の台所の西側に建つ。湯殿を南北棟，桁行１間半，梁間１間の規模とし，風呂を東西棟，桁行２間梁間１間の規模とし，両棟が接して建つ。２棟の屋根両側に寄棟及び入母屋の屋根を見せ，共に桟瓦葺とする。軒先の瓦を目地漆喰付きとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005062"},{"id":"00006077","register_sub_id":"101","register_pk":"107062","name":"帆足家本家住宅（富春館）表門","kana":"ほあしけほんけじゅうたく（ふしゅんかん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.15337032,"lng":131.65791163,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.6m、袖塀付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0122","desc":"敷地南側に，道路境からやや奥まって，質蔵と洋館の間に建つ。２間幅の棟門で，木造，切妻造，桟瓦葺とする。中央１間に両引きの板戸及び格子戸を付け，両側を漆喰壁とする。更に両脇に袖塀を付ける。広大な敷地の表構えを構成するが，比較的質素な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006077"},{"id":"00006065","register_sub_id":"101","register_pk":"107050","name":"帆足家本家住宅（富春館）質蔵","kana":"ほあしけほんけじゅうたく（ふしゅんかん）しちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.15326831,"lng":131.65788485,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積80㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0119","desc":"敷地南辺に沿って，主屋の南側に建つ。桁行７間，梁間３間で，土蔵造２階建，切妻造，桟瓦葺とする。棟通りに２本の柱を立て，１階を２室，２階を１室とする。基礎に切石５段を積み，外壁を漆喰塗とし，腰を海鼠壁とする。規模が大きく，落ち着いた意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006065"},{"id":"00005944","register_sub_id":"101","register_pk":"106929","name":"帆足家本家住宅（富春館）主屋","kana":"ほあしけほんけじゅうたく（ふしゅんかん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.153423,"lng":131.6577,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積342㎡","structure_material":"木造2階一部平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0117","desc":"敷地中央にほぼ南面して建つ。桁行１３間，梁間７間の規模で，木造２階建一部平屋，入母屋造，桟瓦葺とする。南側中央に式台玄関を設け，西側に一段高い座敷，北側に仏間，東側に居室を配する。床の間のつくりなど，本家主屋として意匠，材料，技術共に秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005944"},{"id":"00006076","register_sub_id":"101","register_pk":"107061","name":"帆足家本家住宅（富春館）中門","kana":"ほあしけほんけじゅうたく（ふしゅんかん）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.1531463,"lng":131.6577062,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口1.4m、袖塀付、塀延長12m付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0123","desc":"主屋式台玄関の西脇に建ち，間口１間の木造の腕木門で，切妻造，桟瓦葺の屋根を載せ，両脇に袖壁を設ける。南方に延長１２ｍの築地塀を延ばし，質蔵手前で矩折れに西方に延びる。玄関前と主屋南側の庭を区切り，主屋玄関前の格式ある空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006076"},{"id":"00006078","register_sub_id":"101","register_pk":"107063","name":"帆足家本家住宅（富春館）離れ","kana":"ほあしけほんけじゅうたく（ふしゅんかん）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.153419,"lng":131.657501,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0121","desc":"主屋の北側に建ち，桁行４間，梁間４間半の規模で，木造平屋建，寄棟造，桟瓦葺とする。南側に主屋に続く廊下を設け，北側中央に８畳座敷を設ける。床構えは近代の特徴が見られるが，書院風のつくりとし，良材を用い，意匠，技術に秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006078"},{"id":"00006075","register_sub_id":"101","register_pk":"107060","name":"帆足家本家住宅（富春館）塀","kana":"ほあしけほんけじゅうたく（ふしゅんかん）へい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.15316961,"lng":131.65771784,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、延長51m、門及び祠付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0124","desc":"主屋南側の庭の南側と西側を囲い，質蔵北西隅から北に延び，矩折れに宝蔵南西方の木造の祠まで延びる。木造で，石造の基礎の上に建ち，出桁で軒を支え，瓦屋根を載せる。南東隅に小規模な腕木門を開く。つくりが丁寧で，屋敷外周の質の高い景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006075"},{"id":"00005945","register_sub_id":"101","register_pk":"106930","name":"帆足家本家住宅（富春館）宝蔵","kana":"ほあしけほんけじゅうたく（ふしゅんかん）ほうぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.15324695,"lng":131.65745237,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0118","desc":"敷地南西に，石垣を築き周囲より一段高い位置に建つ。桁行６間半，梁間３間で，土蔵造２階建，寄棟造，桟瓦葺とする。１階，２階共に中央に柱１本を立てて１室とし，広い空間をつくる。外壁は漆喰塗で腰を海鼠壁とし，派手さが無く，機能重視の堅実な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005945"},{"id":"00006079","register_sub_id":"101","register_pk":"107064","name":"帆足家本家住宅（富春館）洋館","kana":"ほあしけほんけじゅうたく（ふしゅんかん）ようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県大分市大字中戸次4381-1","lat":33.15346468,"lng":131.65794716,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積119㎡","structure_material":"木造2階一部平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"44 － 0120","desc":"敷地南辺に沿って，質蔵の東方に建つ。桁行３間半，梁間２間半で，木造２階建，寄棟造，桟瓦葺とする。南西隅に玄関，南側に洋室を設け，玄関北側に８畳座敷を付属し，応接棟とする。東側に店舗を付属する。モルタル塗で石造風に目地を入れた外観意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006079"},{"id":"00006368","register_sub_id":"101","register_pk":"107351","name":"吉川家住宅主屋","kana":"よしかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県竹田市大字竹田町21他","lat":32.966286,"lng":131.39473,"geo_status":"db","era":"大正10／大正11増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積209㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0134","desc":"交差点に面した敷地の角に建つ、間口５間半の木造２階建。北側に入母屋破風をみせる入母屋造、桟瓦葺で、東面から北面に掛けて庇を設ける。１階開口部を除く外壁を塗り込め、重厚な外観とする。１階に広い土間、２階に大広間を備える、老舗造酒屋の店舗兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006368"},{"id":"00006370","register_sub_id":"101","register_pk":"107353","name":"吉川家住宅倉庫一","kana":"よしかわけじゅうたくそうこいち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町21他","lat":32.96612836,"lng":131.39471036,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積114㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0136","desc":"主屋の西隣、通りに面して建つ。桁行８間、梁間４間規模の、土蔵造２階建で、切妻造桟瓦葺とする。かつては酒を製造する「酒造所」や酒蔵として使用されていた、大規模な土蔵である。主屋と連続して、長大な白壁の景観をみせ、趣のある佇まいを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006370"},{"id":"00006372","register_sub_id":"101","register_pk":"107355","name":"吉川家住宅倉庫三","kana":"よしかわけじゅうたくそうこさん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町21他","lat":32.96611336,"lng":131.39491891,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0138","desc":"敷地の南西奥寄りに建つ。建築面積８６㎡、木造２階建、切妻造桟瓦葺である。もと「室（麹室）」として使用されていた建物で、土間床とし、内部に「室」の名残をとどめている。酒造の一工程を担っていた施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006372"},{"id":"00006371","register_sub_id":"101","register_pk":"107354","name":"吉川家住宅倉庫二","kana":"よしかわけじゅうたくそうこに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町21他","lat":32.96611559,"lng":131.39480959,"geo_status":"db","era":"明治11／明治41増築","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造2階建、瓦葺、建築面積179㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0137","desc":"倉庫一の背後に建つ。建築面積１７９㎡、木造２階建、桟瓦葺である。米を蒸すための「釜場」や井戸が残る「洗米所」や、酒を保管する「酒蔵」、酒造り職人のための「休憩所」や「寝室」などが内部に設けられた。酒造業に必要な一連の施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006371"},{"id":"00006369","register_sub_id":"101","register_pk":"107352","name":"吉川家住宅土蔵","kana":"よしかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町21他","lat":32.96627,"lng":131.394836,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0135","desc":"主屋の南隣に建つ、桁行３間半、梁間３間、土蔵造２階建、切妻造妻入桟瓦葺。もとは１階が米蔵、２階が物置。通りに面する妻壁は、出入口と２階窓の上部に瓦葺の庇を付し、窓枠の細工を丁寧に仕上げ、主屋とともに、造酒屋らしい景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006369"},{"id":"00000922","register_sub_id":"101","register_pk":"101912","name":"油津赤レンガ館（旧河野宗泰家倉庫）","kana":"あぶらつあかれんがかん（きゅうかわのむねやすけそうこ）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県日南市油津1-9-3","lat":31.58357593,"lng":131.40295386,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造２階建，瓦葺，建築面積132㎡","structure_material":"煉瓦造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"45 － 0005","desc":"堀川運河の東方，中町通りに北面して建つ。煉瓦造２階建で，内部は左右２室に分かれる。外観は，出入口の門構えの意匠等に工夫がみられる。港湾と運河による水運で栄えた町の様子をよく示す建物で，現在は地域文化活動の拠点として再利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000922"},{"id":"00009245","register_sub_id":"101","register_pk":"164798","name":"池田家住宅主屋","kana":"いけだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市別府町53-1","lat":31.91205658,"lng":131.42802139,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、瓦葺、建築面積165㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"クラーク通り沿いに建つ。木造平屋1部2階建、入母屋及び切妻造桟瓦葺、建築面積165平方メートル。中廊下型の和風住宅北東に配する応接間は、急勾配の切妻屋根で屋根窓を設け、外壁を下見板張やタイル貼として洋風意匠とする。宮崎市街に残る和洋折衷住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009245"},{"id":"00006131","register_sub_id":"101","register_pk":"107115","name":"甲斐家住宅主屋","kana":"かいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県東臼杵郡椎葉村大字不土野778","lat":32.49430522,"lng":131.02820658,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積187㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"45 － 0046","desc":"東側斜面の敷地に建つ。桁行１０間半，梁間４間半の規模で，木造平屋建，入母屋造，鉄板葺とする。山側の西面を壁とし，谷側の東側に縁側を付け，北側から東西２室のコザ，デイ，ウチネ計６室を並べ，玄関を付けないなど，典型的な椎葉型の間取とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006131"},{"id":"00005535","register_sub_id":"101","register_pk":"106523","name":"旧伊東家別荘","kana":"きゅういとうけべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"宮崎県","address":"宮崎県日南市大字風田3585","lat":31.609053,"lng":131.419601,"geo_status":"db","era":"元治元／明治期・昭和42年移築","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0043","desc":"敷地中央に建ち，桁行７間，梁間５間の規模で，木造平屋建，寄棟造，桟瓦葺とする。西側に入母屋造の玄関を付ける。南東隅に１０畳の座敷を構え，その西側に１０畳間を続け，続き間座敷の形式をとる。江戸時代末期の武家住宅の形式を残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005535"},{"id":"00014553","register_sub_id":"101","register_pk":"513967","name":"旧江夏岩吉家住宅主屋","kana":"きゅうえなついわきちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県都城市西町3747","lat":31.71913611,"lng":131.053375,"geo_status":"db","era":"大正15年／昭和10年増築、令和3年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"45 - 0114","desc":"大淀川と薩摩街道脇往還に面する敷地に西面して建つ。地域産業の発展に寄与した味噌醤油業経営者の元住居。木造平屋建、入母屋造で庭に面して広縁を廻らす。小壁黒漆喰塗、洋室外壁を石積風モルタル塗洗出仕上とし、全体に良材を用いた上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014553"},{"id":"00000923","register_sub_id":"101","register_pk":"101913","name":"旧河野宗泰家主屋及び炊事場","kana":"きゅうかわのむねやすけしゅおくおよびすいじば","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"宮崎県","address":"宮崎県日南市油津1-9-3","lat":31.58335712,"lng":131.40297328,"geo_status":"db","era":"江戸末期／大正11頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造２階建，瓦葺，建築面積173㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"45 － 0006","desc":"油津の町並中心を東西に走る下町通りに南面して建つ。接道して居住部分を配し，後方に炊事場を置く。居住部分は通常の町家に似るが，東側に道からわずかに後退して２階建の座敷（大正期増築）を設ける点に特徴がある。上京屋の愛称で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000923"},{"id":"00013473","register_sub_id":"101","register_pk":"368569","name":"旧鈴木馬左也別邸主屋","kana":"きゅうすずきまさやべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡高鍋町大字南高鍋字筏554","lat":32.12535833,"lng":131.50656667,"geo_status":"db","era":"大正12年頃／平成11年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"45 － 0108","desc":"高鍋城旧武家町に位置する、住友三代総理事鈴木馬左也の別邸。木造平屋建、寄棟造、妻入で、東面南寄りに入母屋造の玄関を設ける。玄関北側を家政部とし、廊下を介して田字形に室を配し、奥二室を座敷とする。玄関南には茶室を張出す。堅実な造りの別邸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013473"},{"id":"00013474","register_sub_id":"101","register_pk":"368570","name":"旧鈴木馬左也別邸土蔵","kana":"きゅうすずきまさやべっていどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡高鍋町大字南高鍋字筏554","lat":32.12544167,"lng":131.50649167,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造一部鉄筋コンクリート造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造一部鉄筋コンクリート造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"45 － 0109","desc":"主屋北側の廊下西端に下見板張の前室を介して建つ。土蔵造二階建だが、一階北半の室のみ鉄筋コンクリート造とし、北面に両開鉄扉を開く。外壁は漆喰塗で上部に鉢巻を設け、内部は一階を二室、二階を一室とし、家財を納めた。近代的な工夫を見せる別邸の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013474"},{"id":"00013475","register_sub_id":"101","register_pk":"368571","name":"旧鈴木馬左也別邸土塀","kana":"きゅうすずきまさやべっていどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡高鍋町大字南高鍋字筏554","lat":32.12526667,"lng":131.50675,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土塀、瓦葺、総延長40m","structure_material":"土塀","registered":"2020.08.17(令和2.08.17)","register_no":"45 － 0110","desc":"敷地前面を画する土塀。表門の南北に接続し、南側は敷地境界に沿って矩折れとする。塀の上半は漆喰塗練塀に桟瓦葺の屋根を載せ、下半は表面を平坦に仕上げた下広がりの乱石積とし、漆喰塗との間に水切瓦を廻す。旧武家町の歴史的景観の一部を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013475"},{"id":"00005532","register_sub_id":"101","register_pk":"106520","name":"旧服部家別荘","kana":"きゅうはっとりけべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県日南市西町1-502","lat":31.58255394,"lng":131.40132551,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0041","desc":"油津港河口近くの堀川運河西岸に位置し，南北に長い敷地中央に建つ。桁行９間，梁間８間の規模で，木造平屋建，寄棟造，桟瓦葺とする。南東隅に８畳間の座敷をとり，縁を廻し，広大な日本庭園を望む。豪商の別荘として建てられ，豊かな景観が創られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005532"},{"id":"00005533","register_sub_id":"101","register_pk":"106521","name":"旧服部家別荘土蔵","kana":"きゅうはっとりけべっそうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市西町1-502","lat":31.58277294,"lng":131.40144291,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造平屋一部2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0042","desc":"西側道路に近接して，敷地北方に建ち，桁行７間，梁間３間の規模で，土蔵造平屋一部２階建，切妻造，桟瓦葺とする。内部を２室に分け，東側にそれぞれ戸口を開き，庇をかけ，引戸を付ける。牛梁に登り梁を架ける。規模は大きいが意匠的には簡素な蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005533"},{"id":"00012463","register_sub_id":"101","register_pk":"531787","name":"旧持永家住宅隠居棟","kana":"きゅうもちながけじゅうたくいんきょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県都城市庄内町12625-1","lat":31.77151944,"lng":131.0208,"geo_status":"db","era":"明治40年／大正期増築、昭和中期改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"45-95","desc":"庄内町の中心部の高台に敷地を構え、北面して建つ。入母屋造平入で四周に下屋を廻し、正面に玄関や便所棟を突出する。良質の杉材を用い、東端に十畳の客間を置き、座敷飾も整然とした意匠をもつ。伝統的かつ上質なつくりで、屋敷構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012463"},{"id":"00012464","register_sub_id":"101","register_pk":"531788","name":"旧持永家住宅門及び石塀","kana":"きゅうもちながけじゅうたくもんおよびいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県都城市庄内町12625-1","lat":31.77130278,"lng":131.02108333,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"門 石造、間口1.3m 石塀 石造、総延長75m、石垣付","structure_material":"門 石造","registered":"2018.05.10(平成30.05.10)","register_no":"45-96","desc":"敷地南面から東面にかけて築かれた石垣上に建つ。石塀は切石四段積で上段に丸窓を連続させ、笠石を載せる。南面東寄りを切欠いて階段と門を設け、門柱頂部を繰形付の笠石で飾る。重厚さと軽快さを併せもち、存在感のある屋敷背面の構えをつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012464"},{"id":"00012465","register_sub_id":"101","register_pk":"531789","name":"旧吉田家住宅主屋","kana":"きゅうよしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"宮崎県","address":"宮崎県児湯郡高鍋町大字北高鍋字小丸824","lat":32.13526944,"lng":131.5103,"geo_status":"db","era":"文久2年（1862）／昭和前期・同21年・平成17年・同20年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"45-97","desc":"高鍋城下旧武家地の小丸地区にある。平屋建で東面して建ち、土間と八畳二室を横一列に並べ、奥の八畳を床の間付の接客空間とする。後方に居室二室を突出させ、Ｌ字形に屋根をかける。高鍋藩に仕えた中級武家の住宅で、旧城下の歴史的景観を伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012465"},{"id":"00004305","register_sub_id":"101","register_pk":"105295","name":"黒木家住宅座敷棟","kana":"くろきけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県えびの市大字大河平字小牧4983-4","lat":32.05084272,"lng":130.89075581,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"45 － 0027","desc":"主屋後方の南東隅，雁行状に接続している増築部。木造平屋建，入母屋造で，周囲に下屋を廻し，桟瓦葺とする。平面は床付の８畳２室に縁を廻した形式で，全体は端正なつくりとしている。銘木を用いた床廻りは，全体構成や狆潜などに独特な造形が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004305"},{"id":"00004304","register_sub_id":"101","register_pk":"105294","name":"黒木家住宅主屋","kana":"くろきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県えびの市大字大河平字小牧4983-4","lat":32.05089895,"lng":130.89055885,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"45 － 0026","desc":"木造平屋建，入母屋造，桟瓦葺で，西妻面には入母屋造の玄関を突出し，複雑な屋根になる。中廊下を用いて２列に並べた室構成で，周囲に縁を廻し，開放的に扱う。良材を用い，床廻り，天井，建具などには手の込んだ造形を施す。当地における近代和風の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004304"},{"id":"00004306","register_sub_id":"101","register_pk":"105296","name":"黒木家住宅台所棟","kana":"くろきけじゅうたくだいどころとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県えびの市大字大河平字小牧4983-4","lat":32.0510163,"lng":130.89045865,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"45 － 0028","desc":"主屋の北西方に連続している。木造平屋建，片入母屋造で，下屋庇を廻し，一部に落棟の突出部を設け，総桟瓦葺とする。内部は床張部と土間部からなり，軸部は高く組み，上部の壁に採光の高窓を設ける。附属的な施設ながら，主屋に合わせた丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004306"},{"id":"00004307","register_sub_id":"101","register_pk":"105297","name":"黒木家住宅土蔵","kana":"くろきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県えびの市大字大河平字小牧4983-4","lat":32.05099477,"lng":130.89074596,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"45 － 0029","desc":"主屋後方に座敷棟と並行して建つ。切妻造，桟瓦葺，妻入の２階建土蔵で，外壁は漆喰塗とする。蔵前には直接主屋から延びた廊下が接し，その上部に小庇付の窓を配している。軒廻りの鉢巻，壁面中段の水切など，簡明であるが，伝統的な手法によっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004307"},{"id":"00008391","register_sub_id":"101","register_pk":"134033","name":"高橋家住宅主屋","kana":"たかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市飫肥5-4077","lat":31.62511987,"lng":131.35346025,"geo_status":"db","era":"明治中期／大正4年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0071","desc":"本町通りに南面する敷地の西南に位置する。寄棟造桟瓦葺で、下屋をまわし、通り側に入母屋造の玄関、背面に浴室などを付設する。玄関奥にＬ字型に三室配し、座敷にはトコ構えなどを設ける。良材を用い、襖絵や瀟洒な欄間など、良質な数寄屋風座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008391"},{"id":"00008395","register_sub_id":"101","register_pk":"134037","name":"高橋家住宅納屋","kana":"たかはしけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市飫肥5-4077","lat":31.62544558,"lng":131.35348054,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0075","desc":"敷地北辺、西蔵の東に位置する。東西棟の切妻造桟瓦葺で、南面に深い下屋を設け、桁行１１ｍ梁間７．９ｍの規模となる。木造２階建。外壁は南面が竪板張、他が下見板張。１階は中央を土間、左右を板敷とし、西北隅を間仕切る。敷地景観を構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008395"},{"id":"00008394","register_sub_id":"101","register_pk":"134036","name":"高橋家住宅西蔵","kana":"たかはしけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市飫肥5-4077","lat":31.62540906,"lng":131.35335371,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0074","desc":"敷地北辺の西寄りに位置する。東西棟の切妻造桟瓦葺。桁行８．４ｍ梁間４．４ｍで、南面に出入口を設け、庇を掛ける。飫肥石を四段に積み基礎とする、２階建土蔵。外壁は漆喰仕上げとし、南面に各階二ヶ所に窓を開け、正面外観に軽快感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008394"},{"id":"00008392","register_sub_id":"101","register_pk":"134034","name":"高橋家住宅離れ及び台所","kana":"たかはしけじゅうたくはなれおよびだいどころ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市飫肥5-4077","lat":31.6252183,"lng":131.3535607,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0072","desc":"主屋の東、敷地の東辺沿いに延びる。桁行１４ｍの木造平屋建で、切妻造桟瓦葺とする。南半部を離れ、北半部を台所とし、西面は腕木で軒をもち出し、煉瓦敷の通路とする。台所は天井を張らない土間で、井戸やタイル貼の流し、煉瓦造の竈など設備をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008392"},{"id":"00008393","register_sub_id":"101","register_pk":"134035","name":"高橋家住宅東蔵","kana":"たかはしけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市飫肥5-4077","lat":31.62534615,"lng":131.35353229,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0073","desc":"台所の北に位置し、台所と庇で繋がる。桁行１０ｍ梁間４．４ｍの土蔵造２階建、切妻造妻入桟瓦葺で、南面に出入口を開ける。飫肥石を五段に積み基礎とし、壁は漆喰仕上げとする。１、２階とも一室で和小屋組とする。質実で手堅いつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008393"},{"id":"00011029","register_sub_id":"101","register_pk":"208999","name":"土器屋家住宅石蔵","kana":"どきやけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県宮崎市大字富吉4869-3","lat":31.941955,"lng":131.346591,"geo_status":"db","era":"大正12／昭和後期改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造2階建、瓦葺、建築面積33㎡","structure_material":"石造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"45-0084","desc":"宮崎市街の西方、冨吉集落に建つ。石造二階建で、ロンバルド帯を持ち、隅石を浮き上がらせて強調し、二階床部分の石も帯状に張り出す。出入口部分はアーチ状に石材を組み合わせ、幾何意匠を施す。窓廻りに恵比須天や大黒天を刻むなど、高い加工技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011029"},{"id":"00011030","register_sub_id":"101","register_pk":"209000","name":"土器屋家住宅石塀","kana":"どきやけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県宮崎市大字富吉4869-2他","lat":31.94195392,"lng":131.34642347,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、総延長37m","structure_material":"石造","registered":"2016.02.25(平成28.02.25)","register_no":"45-0085","desc":"敷地の南辺を画する石塀。中央に門口一所を開く。下部に土留めの石積みを設け、その上に四段ほど整層積で切石を積んで塀とし、上部に笠石を載せる。高さは高いところで一・八メートルを超えるもので、旧家の佇まいを構成し、地域の歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011030"},{"id":"00006132","register_sub_id":"101","register_pk":"107116","name":"那須家住宅主屋","kana":"なすけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県東臼杵郡椎葉村大字不土野1503","lat":32.43409509,"lng":131.05398709,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"45 － 0047","desc":"南側斜面の敷地に建つ。桁行１２間，梁間４間半規模で，木造平屋建，入母屋造，桟瓦葺とする。北面を壁とし，東端から南北２室のコザ，デイ，ツボネ計６室とウチネ１室を並べ，西端をドジ（土間）とする。規模が大きく，檜材を多用し，材料，意匠が優秀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006132"},{"id":"00011027","register_sub_id":"101","register_pk":"208997","name":"松浦家住宅石蔵","kana":"まつうらけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市大字柏原字高野迫986イ","lat":31.939858,"lng":131.372406,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造2階建、瓦葺、建築面積25㎡","structure_material":"石造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"45-0082","desc":"宮崎市街の西方、柏原集落に建つ。石造二階建で、ロンバルド帯を持ち、隅石を浮き上がらせて強調し、二階床部分の石も帯状に張り出して唐草文を入れ、出入口脇には錫杖彫を入れるなど、和洋意匠を混交した秀作である。当地域の石工による高い技術を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011027"},{"id":"00011028","register_sub_id":"101","register_pk":"208998","name":"松浦家住宅門柱及び石塀","kana":"まつうらけじゅうたくもんちゅうおよびいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市大字柏原字高野迫986イ","lat":31.939994,"lng":131.37241216,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"表門 石造、間口3.1m 裏門 石造、間口3.2m 石塀 石造、総延長34m","structure_material":"表門 石造","registered":"2016.02.25(平成28.02.25)","register_no":"45-0083","desc":"敷地の東辺を画す石塀と、そこに二所開けられた門柱からなる。門柱は二所とも高さ二・三メートルの石柱を立て、正面には装飾を施し、上部に笠石を載せる。石塀は江戸切仕上の切石を整層積にし、高さ約一・七メートルとなる。集落の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011028"},{"id":"00005531","register_sub_id":"101","register_pk":"106519","name":"渡邊家住宅小蔵","kana":"わたなべけじゅうたくこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市油津2-3-1","lat":31.58304141,"lng":131.40313728,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0040","desc":"主屋の後方，南側に建ち，桁行３間半，梁間２間の規模で，土蔵造平屋建，切妻造，桟瓦葺とする。妻入とし，北側に戸口を開き，西面に窓１箇所を開く。外壁を漆喰塗とし，軒裏まで塗り込める。薪等の収納に使われ，酒蔵と並んで建つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005531"},{"id":"00005529","register_sub_id":"101","register_pk":"106517","name":"渡邊家住宅酒蔵","kana":"わたなべけじゅうたくさかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市油津2-3-1","lat":31.58305412,"lng":131.40320425,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積67㎡","structure_material":"土蔵造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0038","desc":"主屋の南東に建ち，桁行５間，梁間３間の規模で，土蔵造平屋建，切妻造，桟瓦葺とし，北妻面西寄りに瓦葺の庇をかけ，両開きの土戸を開く。外壁を漆喰塗とし，軒裏まで波形に塗り込め，戸口上部の庇も塗り込めとする。当家の一時期の生業の跡を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005529"},{"id":"00005528","register_sub_id":"101","register_pk":"106516","name":"渡邊家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"宮崎県","address":"宮崎県日南市油津2-3-1","lat":31.58321974,"lng":131.40303162,"geo_status":"db","era":"江戸末期／昭和初期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0037","desc":"敷地北辺の道路際に建ち，桁行９間，梁間４間半の規模で，後方に台所等を張り出す。木造平屋建，切妻造，桟瓦葺とする。間口の広い正面東端に出入口を設け，その他を格子窓とし，西側面は漆喰の塗壁とする。江戸末期の油津の商家建築の外観を保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005528"},{"id":"00005530","register_sub_id":"101","register_pk":"106518","name":"渡邊家住宅西蔵","kana":"わたなべけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市油津2-3-1","lat":31.58301987,"lng":131.40301701,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積72㎡","structure_material":"土蔵造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0039","desc":"敷地南西隅に建ち，桁行６間，梁間３間の規模で，土蔵造平屋建，切妻造，桟瓦葺とし，内部を２つに分け，東面にそれぞれ引き戸付きの戸口を開き，平入とする。外壁は正面を横板張りとし，他三方は漆喰塗で腰を板張りとする。家財道具や建具の収納に使われた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005530"},{"id":"00006662","register_sub_id":"101","register_pk":"107645","name":"奄美ばしゃ山民俗村旧安田家住宅主屋","kana":"あまみばしゃやまみんぞくむらきゅうやすだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県奄美市笠利町大字用安字車万川1505-1","lat":28.40384822,"lng":129.64814273,"geo_status":"db","era":"江戸末期／平成15移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0050","desc":"分棟型民家のオモテ部分で、桁行４間半梁間３間半、寄棟造鉄板葺とし、正面左手に玄関を設ける。室内は、玄関奥に４畳半のコザを前後に並べ、右手に主室１０畳を配する。主室にはトコと棚を設ける。奄美における古い形態を伝える住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006662"},{"id":"00012269","register_sub_id":"101","register_pk":"353070","name":"市来大迫家住宅","kana":"いちきおおさこけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県いちき串木野市湊町三丁目12","lat":31.693214,"lng":130.292608,"geo_status":"db","era":"大正5年／昭和16年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積329㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"46-122","desc":"敷地中央に東面する。木造平屋建で、玄関奥に六畳、八畳、八畳座敷を並べ、北に洋室を配し、さらに廊下を延ばして内玄関へと続き、廊下両側に居室を配す。北端部には炊事場、浴室を置く。建具、天井、欄間などに繊細な意匠をみせる大規模近代和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012269"},{"id":"00013774","register_sub_id":"101","register_pk":"504982","name":"岩元家住宅主屋","kana":"いわもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市坊津町秋目794","lat":31.35903889,"lng":130.199625,"geo_status":"db","era":"明治前期／昭和中期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積173㎡","structure_material":"木造平屋一部2階建","registered":"2021.02.26(令和3.02.26)","register_no":"46 － 124","desc":"海沿いの秋目麓集落入口に位置するもと網元の住宅。主体部は入母屋造桟瓦葺で通りに妻を見せ、南側に倉庫を建てて間を門口とし、外壁は竪板張。内部は二列四室の北に六畳を張出す。主座敷は床の左右に床脇と仏壇を設ける。集落のランドマークとなる伝統民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013774"},{"id":"00010086","register_sub_id":"101","register_pk":"196233","name":"鹿児島県民教育文化研究所","kana":"かごしまけんみんきょういくぶんかけんきゅうじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市春日町4-1","lat":31.60589518,"lng":130.56397724,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積587㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"46 － 0115","desc":"中庭の東側に玄関を構え、南の主庭側に上質な座敷飾の一四畳半などを並べた客座敷、北側に旧台所などを配する。南西に張出す別座敷は数寄屋意匠で、南東側に低床の下屋を廻らす。各室の造作に民芸風意匠や奇木を巧みに採用し、自由で創意あふれる構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010086"},{"id":"00009693","register_sub_id":"101","register_pk":"194689","name":"旧鯵坂家住宅石塀","kana":"きゅうあじさかけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下鴻巣17830-1","lat":31.41291935,"lng":130.31841429,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、総延長52m","structure_material":"石造","registered":"2013.06.21(平成25.06.21)","register_no":"46 － 0109","desc":"住宅西側の市道沿いと敷地内の通路沿いに築かれた石塀。江戸切仕上げの直方体の凝灰岩布石を、高さ一メートル内外に精緻に積上げ、総延長五二メートルを測る。出隅部では最上段の積石上角を反らせる細工がされており、加世田集落の屋敷構えの特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009693"},{"id":"00009690","register_sub_id":"101","register_pk":"194686","name":"旧鯵坂家住宅主屋","kana":"きゅうあじさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下鴻巣17830-1","lat":31.41291929,"lng":130.31856117,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積224㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"46 － 0106","desc":"敷地中央に南面し、木造平屋建、入母屋造桟瓦葺で下屋を廻らす。正面東寄りに玄関を構え、北面西端に奥座敷を張出す。前列西側の表座敷では、トコの左右に床脇を配す。室内壁を赤色とし、繊細な欄間をたてるなど、麓集落加世田の住宅形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009690"},{"id":"00009692","register_sub_id":"101","register_pk":"194688","name":"旧鯵坂家住宅門","kana":"きゅうあじさかけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下鴻巣17830-1","lat":31.41277414,"lng":130.31843982,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口1.9m、左右袖塀付","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"46 － 0108","desc":"敷地西面南端の市道沿いに構える。一間腕木門、切妻造桟瓦葺で、本柱後方に石製の控柱を立てて腕木を支持する独特な形式。門の左右に落棟の袖塀を設け、その両端から前方にのばす塀をさらに落棟とし、基礎を凝灰岩切石積とするなど、変化のある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009692"},{"id":"00009691","register_sub_id":"101","register_pk":"194687","name":"旧鯵坂家住宅蔵","kana":"きゅうあじさかけじゅうたくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下鴻巣17830-1","lat":31.41278604,"lng":130.31871584,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"46 － 0107","desc":"敷地南東隅に東西棟で建ち、桁行六メートル梁間五メートル、土蔵造二階建、切妻造桟瓦葺で、東面に土蔵造の下屋を、北面の戸口に吹放しの下屋を設ける。布石を腰高に三段積んで基礎とし、外壁を漆喰塗とし、西面上下階に小窓を穿つ。屋敷景観を引立てる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009691"},{"id":"00011609","register_sub_id":"101","register_pk":"210528","name":"旧上妻家住宅主屋","kana":"きゅうこうづまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県西之表市西之表9819","lat":30.73081694,"lng":130.99716306,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積210㎡","structure_material":"木造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"46-0119","desc":"種子島の北寄り、西之表麓の南西に位置する武家住宅。見通しの良い小高い丘の上に建つ。主屋は南北二列に室を並べ、南列を接客用座敷、北列を居室とする。北列東室はもと土間とみられる。内部造作もトコ構えを板壁とするなど、地域の特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011609"},{"id":"00011610","register_sub_id":"101","register_pk":"210529","name":"旧上妻家住宅門","kana":"きゅうこうづまけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県西之表市西之表字下小牧9819-2","lat":30.73067111,"lng":130.99727,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"46-0120","desc":"敷地の南辺に開く腕木門。主柱の前後に控柱を出す。軒は一軒疎垂木で、桟瓦を葺く。冠木中央に左右笈型付の束を立てる。全体に簡素ながらも、腕木の実肘木などに繰型を施すなど、細部に装飾を持つ。敷地のソテツなどと相まって、南国の武家屋敷の構えを示す","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011610"},{"id":"00010082","register_sub_id":"101","register_pk":"196229","name":"旧重富島津家別邸石塀","kana":"きゅうしげとみしまづけべっていいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市清水町18","lat":31.60808594,"lng":130.57297446,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造及び煉瓦造、瓦葺、総延長24m","structure_material":"石造及び煉瓦造","registered":"2014.04.25(平成26.04.25)","register_no":"46 － 0111","desc":"主屋の謁見の間南東隅から、南に折曲がりにのびる石塀で、総延長二四メートルを測る。溶結凝灰岩の切石を布積みし、さらにイギリス積の煉瓦塀を積み重ね、桟瓦葺とする。敷地の起伏に応じて屈曲し、高低も変えており、重厚な形式ながら変化のある景観を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010082"},{"id":"00010081","register_sub_id":"101","register_pk":"196228","name":"旧重富島津家別邸主屋","kana":"きゅうしげとみしまづけべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市清水町18","lat":31.60822412,"lng":130.57281779,"geo_status":"db","era":"明治後期／平成17改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積289㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"46 － 0110","desc":"敷地中央に南面し、謁見の間など三棟を雁行配置して各々に縁と下屋を廻らせ、東端に入母屋造の玄関を構える。各室内には、黒ガキなどの銘木を使い意匠も優れた座敷飾を構える。また室境の透彫欄間や杉戸等の建具も気品を備えている。旧大名家の上質な別邸建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010081"},{"id":"00008799","register_sub_id":"101","register_pk":"149520","name":"鮫島家住宅石塀","kana":"さめしまけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18275","lat":31.41340829,"lng":130.31744601,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、総延長72m","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0101","desc":"蔵の西側の部分と、門から通り沿いに東へ延び、東面を画し、北端で西に折れる部分からなる。総延長72ｍ。地元産の凝灰岩を大きいもので長さ1.0ｍ高さ0.25ｍ厚さ0.30ｍの切石として積み上げ、上部に生垣を設ける。加世田麓の集落景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008799"},{"id":"00008796","register_sub_id":"101","register_pk":"149517","name":"鮫島家住宅井戸","kana":"さめしまけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18274-1","lat":31.4135362,"lng":130.3172164,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、面積1.3㎡","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0098","desc":"屋敷正面の通りの奥に位置する。正面1.2ｍ奥行1.1ｍの三方を凝灰岩の切石を積み上げ、石板を並べて片流屋根をかけて囲い、正面に両開板戸をたてる。その前方から北面まわりに石を貼り、洗い場とし、北側に水神を祀る。当時の生活を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008796"},{"id":"00008794","register_sub_id":"101","register_pk":"149515","name":"鮫島家住宅内蔵","kana":"さめしまけじゅうたくうちくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18275","lat":31.41375074,"lng":130.31746074,"geo_status":"db","era":"明治後期／平成10年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0096","desc":"主屋台所の北に南北棟で建つ。桁行7.0ｍ梁間5.1ｍの土蔵造二階建、切妻造桟瓦葺、東面に奥行3.2ｍの深い庇を付ける。外壁は漆喰仕上げ。内部1階は南北2室に分かれ、2階は1室。高い礎石を用いて床下を高さ70㎝にして、湿気対策をする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008794"},{"id":"00008795","register_sub_id":"101","register_pk":"149516","name":"鮫島家住宅蔵","kana":"さめしまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18275","lat":31.41355408,"lng":130.31728394,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0097","desc":"主屋の前方、通り沿いに位置する。桁行7.9ｍ梁間4.0ｍの土蔵造平屋建。切妻造桟瓦葺で、北面を葺き降ろして蔵前を設ける。通り側は切石を高く積み上げる。外壁は漆喰仕上げで、北面には引込戸をたてる。内部は二室。重厚な通り景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008795"},{"id":"00008793","register_sub_id":"101","register_pk":"149514","name":"鮫島家住宅主屋","kana":"さめしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18275","lat":31.41362361,"lng":130.31747266,"geo_status":"db","era":"明治後期／平成10年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0095","desc":"加世田の麓集落、山麓の傾斜地に屋敷地を占める。主屋は座敷棟と台所棟からなる分棟型の住宅で、建築面積285㎡。台所棟は切妻造、座敷棟は東入母屋西切妻造、桟瓦葺。上屋を大壁とし漆喰で塗り込める。開放的な座敷など、地域的特色を伝える近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008793"},{"id":"00008798","register_sub_id":"101","register_pk":"149519","name":"鮫島家住宅坪庭門","kana":"さめしまけじゅうたくつぼにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18275","lat":31.41355628,"lng":130.31742375,"geo_status":"db","era":"明治後期／平成10年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、間口1.3m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0100","desc":"門から主屋への通路と主屋座敷前の庭を画する門。切妻造桟瓦葺。両脇は木立が続く。間口1.3ｍの腕木門。切石礎石上に方柱をたて、楣で固め棟木を架す。楣・棟木間には流水に鴎を彫る板欄間を装置。一軒疎垂木。背面に控えを付ける。庭を彩る軽快な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008798"},{"id":"00008797","register_sub_id":"101","register_pk":"149518","name":"鮫島家住宅門","kana":"さめしまけじゅうたくもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田字下上鴻巣18275","lat":31.41350879,"lng":130.31735648,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"46 － 0099","desc":"蔵の東に接して建つ長屋門。桁行7.4ｍ梁間4.0ｍの木造2階建、西切妻東寄棟造桟瓦葺で、正・背面に庇を付設。通り側は切石を高く積み上げる。1階西寄りを門口とし、両開戸を吊る。2階は居室とする。漆喰仕上げの大壁造で、矩形の窓を穿つ外観が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008797"},{"id":"00009413","register_sub_id":"101","register_pk":"194206","name":"鮫島博家住宅石塀","kana":"さめしまひろしけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田17824-1","lat":31.41373328,"lng":130.31875976,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、総延長49m","structure_material":"石造","registered":"2012.08.13(平成24.08.13)","register_no":"46 － 0105","desc":"門の左右に折曲がりに延びる塀と、門後方の牆壁からなる。凝灰岩切石を布積とし、高さ二・一メートル、総延長四九メートルを測る。中段で積石の外上角を斜めに突出させる独特の技法で築かれ、敷地内に植栽されたイヌマキとともに加世田郷の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009413"},{"id":"00009411","register_sub_id":"101","register_pk":"194204","name":"鮫島博家住宅蔵","kana":"さめしまひろしけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田17824-1","lat":31.4136017,"lng":130.31871178,"geo_status":"db","era":"明治前期／平成8年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"46 － 0103","desc":"敷地西隅に建ち、土蔵造平屋建、桁行五・一メートル梁間四・一メートル、切妻造桟瓦葺である。南東妻面を出入口として下屋を設け、北西妻面に小窓を穿つ。凝灰岩切石布積の基礎上に建ち、外壁は漆喰塗で仕上げる。敷地入口脇にあって屋敷構えを引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009411"},{"id":"00009410","register_sub_id":"101","register_pk":"194203","name":"鮫島博家住宅主屋","kana":"さめしまひろしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田17824-1","lat":31.41366356,"lng":130.31892355,"geo_status":"db","era":"明治前期／昭和中期・昭和後期・平成8年・平成11年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"46 － 0102","desc":"敷地北寄りに南西面して建つ。木造平屋建、建築面積一六九平方メートル、入母屋造桟瓦葺で下屋を廻らす。正面中央に玄関を構え六室を配する。室内は赤色の土壁を塗り、奥座敷のトコ脇には軍配形窓を穿ち、瀟洒な内観とする。加世田郷の武家住宅形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009410"},{"id":"00009412","register_sub_id":"101","register_pk":"194205","name":"鮫島博家住宅門","kana":"さめしまひろしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田17824-1","lat":31.41369069,"lng":130.31873023,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口1.8m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"46 － 0104","desc":"敷地北西の通りから後退して建つ。間口一・八メートルの腕木門、切妻造桟瓦葺で、左右に袖塀を折曲がりに延ばす。門は楣上に格子を組み、垂木には反りをもたせる。袖塀は腰を簓子下見板張とし、上部を竪板張とする。風格あるつくりで武家住宅の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009412"}];
